           # Tool call terminals\n            "TOOL_START": tool_start,\n            "TOOL_END": tool_end,\n            "FUNC_PREFIX": FUNC_PREFIX,\n            "FUNC_END": FUNC_END,\n            "PARAM_START": PARAM_START,\n            "PARAM_END": PARAM_END,\n            "CLOSE_ANGLE": ">",\n        },\n        token_id_terminals={\n            "THINK_START": think_start,\n            "THINK_END": think_end,\n            "TOOL_START": tool_start,\n            "TOOL_END": tool_end,\n        },\n        transitions={\n            # -- Reasoning transitions --\n            (ParserState.REASONING, "THINK_START"): Transition(\n                ParserState.REASONING,\n                (),\n            ),\n            (ParserState.REASONING, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (EventType.REASONING_END,),\n            ),\n            # Absorb duplicate </think> — model may emit it after\n            # already transitioning to CONTENT; drop it silently.\n            (ParserState.CONTENT, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            # Tool call directly from reasoning (implicit end)\n            (ParserState.REASONING, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (EventType.REASONING_END, EventType.TOOL_CALL_START),\n            ),\n            # -- Tool call transitions --\n            (ParserState.CONTENT, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (EventType.REASONING_END, EventType.TOOL_CALL_START),\n            ),\n            # Fallback: <function= without a preceding <tool_call>\n            (ParserState.CONTENT, "FUNC_PREFIX"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.TOOL_CALL_START,),\n            ),\n            (ParserState.TOOL_PREAMBLE, "TOOL_END"): Transition(\n                ParserState.CONTENT,\n                (EventType.TOOL_CALL_END,),\n            ),\n            (ParserState.TOOL_PREAMBLE, "FUNC_PREFIX"): Transition(\n                ParserState.TOOL_NAME,\n                (),\n            ),\n            (ParserState.TOOL_NAME, "CLOSE_ANGLE"): Transition(\n                ParserState.TOOL_ARGS,\n                (),\n            ),\n            # Malformed: </function> while still in TOOL_NAME (no closing >)\n            (ParserState.TOOL_NAME, "FUNC_END"): Transition(\n                ParserState.TOOL_BETWEEN,\n                (EventType.TOOL_CALL_END,),\n            ),\n            (ParserState.TOOL_ARGS, "FUNC_END"): Transition(\n                ParserState.TOOL_BETWEEN,\n                (EventType.TOOL_CALL_END,),\n            ),\n            (ParserState.TOOL_ARGS, "PARAM_START"): Transition(\n                ParserState.TOOL_ARGS,\n                (EventType.ARG_VALUE_CHUNK,),\n            ),\n            (ParserState.TOOL_ARGS, "PARAM_END"): Transition(\n                ParserState.TOOL_ARGS,\n                (EventType.ARG_VALUE_CHUNK,),\n            ),\n            (ParserState.TOOL_BETWEEN, "TOOL_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            # Consecutive tool call without closing </tool_call>\n            (ParserState.TOOL_BETWEEN, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (EventType.TOOL_CALL_START,),\n            ),\n            (ParserState.TOOL_BETWEEN, "FUNC_PREFIX"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.TOOL_CALL_START,),\n            ),\n        },\n        arg_converter=_qwen3_arg_converter,\n        stream_arg_deltas=True,\n        strip_trailing_reasoning_whitespace=False,\n        tool_args_json=False,\n    )\n\n\nclass Qwen3Parser(ParserEngine):\n    """Qwen3 parser: ``<think>``/``</think>`` reasoning +\n    ``<tool_call>`` XML tool calls in a single engine.\n\n    - ``<tool_call>`` as implicit reasoning end (a grammar transition, so it\n      also feeds ``is_reasoning_end`` and the structured-output gate)\n\n    Subclasses that share the grammar but differ only in the four wrapper\n    token strings (reasoning + tool-call) override the class attributes\n    below; everything else is inherited unchanged.\n    """\n\n    CONFIG_NAME = "qwen3"\n    THINK_START = THINK_START\n    THINK_END = THINK_END\n    TOOL_START = TOOL_CALL_START\n    TOOL_END = TOOL_CALL_END\n    TURN_BOUNDARIES: frozenset[str] = CHATML_TURN_BOUNDARIES\n\n    def __init__(\n        self,\n        tokenizer: TokenizerLike,\n        tools: list[Tool] | None = None,\n        **kwargs,\n    ) -> None:\n        chat_kwargs = kwargs.get("chat_template_kwargs", {}) or {}\n        self.thinking_enabled = chat_kwargs.get("enable_thinking", True)\n        kwargs.setdefault(\n            "parser_engine_config",\n            qwen3_config(\n                thinking=self.thinking_enabled,\n                name=self.CONFIG_NAME,\n                think_start=self.THINK_START,\n                think_end=self.THINK_END,\n                tool_start=self.TOOL_START,\n                tool_end=self.TOOL_END,\n                turn_boundary_tokens=self.TURN_BOUNDARIES,\n            ),\n        )\n        super().__init__(\n            tokenizer,\n            tools,\n            **kwargs,\n        )\n\n    def extract_reasoning(\n        self,\n        model_output: str,\n        request: ChatCompletionRequest | ResponsesRequest,\n    ) -> tuple[str | None, str | None]:\n        if not self.thinking_enabled:\n            return None, model_output\n        return super().extract_reasoning(model_output, request)\n', False), 'vllm.parser.kimi_k3': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n\nfrom __future__ import annotations\n\nfrom collections.abc import Sequence\nfrom typing import TYPE_CHECKING\n\nfrom vllm.entrypoints.generate.base.protocol import (\n    DeltaMessage,\n    FunctionCall,\n)\nfrom vllm.parser.abstract_parser import DelegatingParser\nfrom vllm.reasoning.kimi_k3_reasoning_parser import KimiK3ReasoningParser\n\nif TYPE_CHECKING:\n    from vllm.entrypoints.openai.chat_completion.protocol import (\n        ChatCompletionRequest,\n    )\n    from vllm.entrypoints.openai.responses.protocol import ResponsesRequest\n\n\nclass KimiK3Parser(DelegatingParser):\n    """Compose the Kimi K3 reasoning and tool parsers for XTML output."""\n\n    # TODO: Switch Kimi K3 to the parser engine once its XTML reasoning/tool\n    # path is covered there.\n    def _extract_tool_calls(\n        self,\n        content: str | None,\n        request: ChatCompletionRequest | ResponsesRequest,\n        enable_auto_tools: bool = False,\n    ) -> tuple[list[FunctionCall] | None, str | None]:\n        if self._tool_parser is None or not enable_auto_tools:\n            return super()._extract_tool_calls(content, request, enable_auto_tools)\n\n        tool_call_info = self.extract_tool_calls(content or "", request=request)\n        if request.tool_choice == "none":\n            return [], tool_call_info.content\n        if not tool_call_info.tools_called:\n            return None, tool_call_info.content\n\n        tool_calls = [\n            FunctionCall(\n                id=tool_call.id,\n                name=tool_call.function.name,\n                arguments=tool_call.function.arguments,\n            )\n            for tool_call in tool_call_info.tool_calls\n        ]\n        parsed_content = tool_call_info.content\n        if parsed_content and parsed_content.strip() == "":\n            parsed_content = None\n        return tool_calls, parsed_content\n\n    def _extract_tool_calls_streaming(\n        self,\n        previous_text: str,\n        current_text: str,\n        delta_text: str,\n        previous_token_ids: Sequence[int],\n        current_token_ids: Sequence[int],\n        delta_token_ids: Sequence[int],\n        request: ChatCompletionRequest | ResponsesRequest,\n        tool_call_idx: int | None = None,\n        tool_call_id_type: str = "random",\n        function_name_returned: bool = False,\n    ) -> tuple[DeltaMessage | None, bool]:\n        if request.tool_choice != "none":\n            return super()._extract_tool_calls_streaming(\n                previous_text,\n                current_text,\n                delta_text,\n                previous_token_ids,\n                current_token_ids,\n                delta_token_ids,\n                request,\n                tool_call_idx=tool_call_idx,\n                tool_call_id_type=tool_call_id_type,\n                function_name_returned=function_name_returned,\n            )\n\n        delta_message = self.extract_tool_calls_streaming(\n            previous_text,\n            current_text,\n            delta_text,\n            previous_token_ids,\n            current_token_ids,\n            delta_token_ids,\n            request,\n        )\n        if delta_message is not None:\n            delta_message.tool_calls = []\n        return delta_message, False\n\n    def parse_delta(\n        self,\n        delta_text: str,\n        delta_token_ids: list[int],\n        request: ChatCompletionRequest | ResponsesRequest,\n        prompt_token_ids: list[int] | None = None,\n        *,\n        finished: bool,\n    ) -> DeltaMessage | None:\n        state = self._stream_state\n        previous_content = state.previous_text if state.reasoning_ended else ""\n        delta_message = super().parse_delta(\n            delta_text,\n            delta_token_ids,\n            request,\n            prompt_token_ids,\n            finished=finished,\n        )\n\n        if (\n            self._tool_parser is not None\n            or not isinstance(self._reasoning_parser, KimiK3ReasoningParser)\n            or not state.reasoning_ended\n            or delta_message is None\n        ):\n            return delta_message\n\n        stripped = self._reasoning_parser.strip_content_streaming(\n            previous_text=previous_content,\n            current_text=state.previous_text,\n        )\n        delta_message.content = stripped.content if stripped is not None else None\n        if (\n            delta_message.role is None\n            and delta_message.content is None\n            and delta_message.reasoning is None\n            and not delta_message.tool_calls\n        ):\n            return None\n        return delta_message\n', False), 'vllm.parser.deepseek_v4': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""DeepSeek V4 parser: ``<think>``/``</think>``\nreasoning plus DSML tool calls in a single state machine.\n\nDeepSeek V4 output format::\n\n    <think>\n    ...reasoning...\n    </think>\n    <｜DSML｜tool_calls>\n    <｜DSML｜invoke name="func_name">\n    <｜DSML｜parameter name="location" string="true">杭州</｜DSML｜parameter>\n    <｜DSML｜parameter name="count" string="false">5</｜DSML｜parameter>\n    </｜DSML｜invoke>\n    </｜DSML｜tool_calls>\n"""\n\nfrom __future__ import annotations\n\nimport contextlib\nimport functools\nimport json\nfrom typing import TYPE_CHECKING\n\nimport regex as re\n\nfrom vllm.parser.engine.events import EventType\nfrom vllm.parser.engine.parser_engine import ParserEngine\nfrom vllm.parser.engine.parser_engine_config import (\n    ParserEngineConfig,\n    ParserState,\n    Transition,\n)\nfrom vllm.tool_parsers.utils import find_tool_properties\n\nif TYPE_CHECKING:\n    from vllm.tokenizers import TokenizerLike\n    from vllm.tool_parsers.abstract_tool_parser import Tool\n\n_DSML = "｜DSML｜"\n\nDSML_THINK_START = "<think>"\nDSML_THINK_END = "</think>"\nDSML_TOOL_START = f"<{_DSML}tool_calls>"\nDSML_TOOL_END = f"</{_DSML}tool_calls>"\nDSML_INVOKE_PREFIX = f\'<{_DSML}invoke name="\'\nDSML_INVOKE_NAME_END = \'">\'\nDSML_INVOKE_END = f"</{_DSML}invoke>"\nDSML_PARAM_START = f"<{_DSML}parameter"\nDSML_PARAM_CLOSE = f"</{_DSML}parameter>"\n\n# Spellings variants of ``DSML_TOOL_START`` observed in production.\nDSML_TOOL_START_VARIANTS: tuple[str, ...] = (\n    f"<{_DSML}toolcalls>",\n    f"<{_DSML}tool>",\n)\n\n_ESCAPED_DSML = re.escape(_DSML)\n_PARAM_RE = re.compile(\n    rf\'<{_ESCAPED_DSML}parameter\\s+name="([^"]+)"\\s+string="(true|false)">\'\n    rf"(.*?)"\n    rf"(?:</{_ESCAPED_DSML}parameter>|(?=<{_ESCAPED_DSML}parameter\\s+name=))",\n    re.DOTALL,\n)\n_PARTIAL_PARAM_RE = re.compile(\n    rf\'<{_ESCAPED_DSML}parameter\\s+name="([^"]+)"\\s+string="(true|false)">\'\n    rf"(.*)$",\n    re.DOTALL,\n)\n\n\ndef _dsml_arg_converter(\n    raw_args: str,\n    partial: bool,\n    *,\n    param_re: re.Pattern = _PARAM_RE,\n    partial_param_re: re.Pattern = _PARTIAL_PARAM_RE,\n) -> str:\n    params: dict[str, object] = {}\n\n    last_end = 0\n    for m in param_re.finditer(raw_args):\n        name, is_str, value = m.group(1), m.group(2), m.group(3)\n        if is_str == "true":\n            params[name] = value\n        else:\n            try:\n                params[name] = json.loads(value)\n            except (json.JSONDecodeError, ValueError):\n                params[name] = value\n        last_end = m.end()\n\n    if partial:\n        pm = partial_param_re.search(raw_args, last_end)\n        if pm:\n            name, is_str, value = pm.group(1), pm.group(2), pm.group(3)\n            if is_str == "true":\n                params[name] = value\n            else:\n                with contextlib.suppress(json.JSONDecodeError, ValueError):\n                    params[name] = json.loads(value)\n\n    return json.dumps(params, ensure_ascii=False)\n\n\ndef _unwrap_wrapper_args(\n    args_json: str,\n    tools: list[Tool] | None,\n    func_name: str | None,\n) -> str:\n    if not tools or not func_name:\n        return args_json\n    try:\n        args = json.loads(args_json)\n    except (json.JSONDecodeError, ValueError):\n        return args_json\n    if not isinstance(args, dict):\n        return args_json\n    properties = find_tool_properties(tools, func_name)\n    if not properties:\n        return args_json\n    allowed = set(properties.keys())\n    for wrapper in ("arguments", "input"):\n        if set(args.keys()) != {wrapper} or wrapper in allowed:\n            continue\n        inner = args[wrapper]\n        if isinstance(inner, str):\n            try:\n                inner = json.loads(inner)\n            except json.JSONDecodeError:\n                return args_json\n        if isinstance(inner, dict) and set(inner.keys()).issubset(allowed):\n            return json.dumps(inner, ensure_ascii=False)\n    return args_json\n\n\n@functools.cache\ndef deepseek_v4_config(thinking: bool = False) -> ParserEngineConfig:\n    return ParserEngineConfig(\n        name="deepseek_v4",\n        initial_state=ParserState.REASONING if thinking else ParserState.CONTENT,\n        wait_for_reasoning=thinking,\n        terminals={\n            "THINK_START": DSML_THINK_START,\n            "THINK_END": DSML_THINK_END,\n            "TOOL_START": (DSML_TOOL_START, *DSML_TOOL_START_VARIANTS),\n            "TOOL_END": DSML_TOOL_END,\n            "INVOKE_PREFIX": DSML_INVOKE_PREFIX,\n            "INVOKE_NAME_END": DSML_INVOKE_NAME_END,\n            "INVOKE_END": DSML_INVOKE_END,\n            "PARAM_START": DSML_PARAM_START,\n            "PARAM_CLOSE": DSML_PARAM_CLOSE,\n        },\n        token_id_terminals={\n            "THINK_START": DSML_THINK_START,\n            "THINK_END": DSML_THINK_END,\n            "TOOL_START": DSML_TOOL_START,\n            "TOOL_END": DSML_TOOL_END,\n        },\n        transitions={\n            (ParserState.CONTENT, "THINK_START"): Transition(\n                ParserState.REASONING,\n                (EventType.REASONING_START,),\n            ),\n            # Absorb a bare </think> with no prior <think>\n            (ParserState.CONTENT, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            # Absorb a duplicate <think> while already reasoning\n            (ParserState.REASONING, "THINK_START"): Transition(\n                ParserState.REASONING,\n                (),\n            ),\n            (ParserState.REASONING, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (EventType.REASONING_END,),\n            ),\n            # Tool call beginning while still inside <think>\n            (ParserState.REASONING, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (EventType.REASONING_END,),\n            ),\n            (ParserState.CONTENT, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (),\n            ),\n            (ParserState.TOOL_PREAMBLE, "INVOKE_PREFIX"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.TOOL_CALL_START,),\n            ),\n            (ParserState.CONTENT, "INVOKE_PREFIX"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.TOOL_CALL_START,),\n            ),\n            (ParserState.TOOL_NAME, "INVOKE_NAME_END"): Transition(\n                ParserState.TOOL_ARGS,\n                (),\n            ),\n            (ParserState.TOOL_ARGS, "INVOKE_END"): Transition(\n                ParserState.TOOL_BETWEEN,\n                (EventType.TOOL_CALL_END,),\n            ),\n            (ParserState.TOOL_ARGS, "TOOL_END"): Transition(\n                ParserState.TOOL_BETWEEN,\n                (EventType.TOOL_CALL_END,),\n            ),\n            # Parallel tool calls\n            (ParserState.TOOL_BETWEEN, "INVOKE_PREFIX"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.TOOL_CALL_START,),\n            ),\n            # A tool call ends the turn: stay in TOOL_BETWEEN so any text\n            # after the block is dropped.\n            (ParserState.TOOL_BETWEEN, "TOOL_END"): Transition(\n                ParserState.TOOL_BETWEEN,\n                (),\n            ),\n            (ParserState.TOOL_BETWEEN, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (),\n            ),\n        },\n        content_events={\n            ParserState.CONTENT: EventType.TEXT_CHUNK,\n            ParserState.REASONING: EventType.REASONING_CHUNK,\n            ParserState.TOOL_NAME: EventType.TOOL_NAME,\n            ParserState.TOOL_ARGS: EventType.ARG_VALUE_CHUNK,\n        },\n        arg_converter=_dsml_arg_converter,\n        arg_structural_chars=frozenset(">"),\n        strip_content_whitespace_with_tools=False,\n        tool_args_json=False,\n    )\n\n\nclass DeepSeekV4Parser(ParserEngine):\n    parser_config = staticmethod(deepseek_v4_config)\n\n    def __init__(\n        self,\n        tokenizer: TokenizerLike,\n        tools: list[Tool] | None = None,\n        **kwargs,\n    ) -> None:\n        chat_kwargs = kwargs.pop("chat_template_kwargs", None) or {}\n        thinking = bool(\n            chat_kwargs.get("thinking") or chat_kwargs.get("enable_thinking")\n        )\n        if "thinking" not in chat_kwargs and "enable_thinking" not in chat_kwargs:\n            thinking = True\n        thinking = thinking and chat_kwargs.get("reasoning_effort") != "none"\n        super().__init__(\n            tokenizer,\n            tools,\n            parser_engine_config=self.parser_config(thinking=thinking),\n            **kwargs,\n        )\n        self._arg_converter = self._convert_args\n\n    def _convert_args(self, raw_args: str, partial: bool) -> str:\n        converter = self.parser_engine_config.arg_converter\n        assert converter is not None\n        result = converter(raw_args, partial)\n        if not self._tools:\n            return result\n        func_name = next((s.name for s in self._tool_slots if s.args == raw_args), None)\n        return _unwrap_wrapper_args(result, self._tools, func_name)\n', False), 'vllm.parser.parser_manager': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n\nfrom __future__ import annotations\n\nfrom typing import TYPE_CHECKING\n\nfrom vllm.logger import init_logger\n\nif TYPE_CHECKING:\n    from vllm.parser.abstract_parser import Parser\n    from vllm.reasoning import ReasoningParser\n    from vllm.tool_parsers import ToolParser\n\nlogger = init_logger(__name__)\n\n\nclass ParserManager:\n    """\n    Provides a unified Parser by composing reasoning and tool parser adapters.\n    """\n\n    @classmethod\n    def get_tool_parser(\n        cls,\n        tool_parser_name: str | None = None,\n        enable_auto_tools: bool = False,\n        model_name: str | None = None,\n    ) -> type[ToolParser] | None:\n        """Get the tool parser based on the name."""\n        from vllm.tool_parsers import ToolParserManager\n\n        parser: type[ToolParser] | None = None\n        if not enable_auto_tools or tool_parser_name is None:\n            return parser\n        logger.info_once(\'"auto" tool choice has been enabled.\')\n\n        try:\n            if (\n                tool_parser_name == "pythonic"\n                and model_name\n                and model_name.startswith("meta-llama/Llama-3.2")\n            ):\n                logger.warning(\n                    "Llama3.2 models may struggle to emit valid pythonic tool calls"\n                )\n            parser = ToolParserManager.get_tool_parser(tool_parser_name)\n        except Exception as e:\n            raise TypeError(\n                "Error: --enable-auto-tool-choice requires "\n                f"tool_parser:\'{tool_parser_name}\' which has not "\n                "been registered"\n            ) from e\n        return parser\n\n    @classmethod\n    def get_reasoning_parser(\n        cls,\n        reasoning_parser_name: str | None,\n    ) -> type[ReasoningParser] | None:\n        """Get the reasoning parser based on the name."""\n        from vllm.reasoning import ReasoningParserManager\n\n        parser: type[ReasoningParser] | None = None\n        if not reasoning_parser_name:\n            return None\n        try:\n            parser = ReasoningParserManager.get_reasoning_parser(reasoning_parser_name)\n            assert parser is not None\n        except Exception as e:\n            raise TypeError(f"{reasoning_parser_name=} has not been registered") from e\n        return parser\n\n    @classmethod\n    def get_parser(\n        cls,\n        tool_parser_name: str | None = None,\n        reasoning_parser_name: str | None = None,\n        enable_auto_tools: bool = False,\n        model_name: str | None = None,\n        is_harmony: bool = False,\n    ) -> type[Parser] | None:\n        """\n        Get a Parser that handles both reasoning and tool parsing.\n\n        Composes the individual parsers into a ``DelegatingParser`` subclass.\n\n        Args:\n            tool_parser_name: The name of the tool parser.\n            reasoning_parser_name: The name of the reasoning parser.\n            enable_auto_tools: Whether auto tool choice is enabled.\n            model_name: The model name for parser-specific warnings.\n            is_harmony: Whether the selected model uses the Harmony format.\n                        If True, HarmonyParser is always returned.\n\n        Returns:\n            A Parser class, or None if neither parser is specified.\n        """\n        if not tool_parser_name and not reasoning_parser_name:\n            return None\n\n        reasoning_parser_cls = cls.get_reasoning_parser(reasoning_parser_name)\n        tool_parser_cls = cls.get_tool_parser(\n            tool_parser_name, enable_auto_tools, model_name\n        )\n\n        if reasoning_parser_cls is None and tool_parser_cls is None:\n            return None\n\n        if is_harmony:\n            from vllm.parser.harmony import HarmonyParser\n\n            HarmonyParser.reasoning_parser_cls = reasoning_parser_cls\n            HarmonyParser.tool_parser_cls = tool_parser_cls\n            return HarmonyParser\n\n        if reasoning_parser_name == "kimi_k3" or tool_parser_name == "kimi_k3":\n            from vllm.parser.kimi_k3 import KimiK3Parser\n\n            r_cls = reasoning_parser_cls\n            t_cls = tool_parser_cls\n\n            class _KimiK3Parser(KimiK3Parser):\n                reasoning_parser_cls = r_cls\n                tool_parser_cls = t_cls\n\n            return _KimiK3Parser\n\n        if {reasoning_parser_name, tool_parser_name} & {\n            "cohere_command3",\n            "cohere_command4",\n        }:\n            from vllm.parser.cohere_command import CohereCommandParser\n\n            r_cls = reasoning_parser_cls\n            t_cls = tool_parser_cls\n\n            class _CohereCommandParser(CohereCommandParser):\n                reasoning_parser_cls = r_cls\n                tool_parser_cls = t_cls\n\n            return _CohereCommandParser\n\n        from vllm.parser.abstract_parser import DelegatingParser\n\n        r_cls = reasoning_parser_cls\n        t_cls = tool_parser_cls\n\n        class _Parser(DelegatingParser):\n            reasoning_parser_cls = r_cls\n            tool_parser_cls = t_cls\n\n        return _Parser\n', False), 'vllm.parser.cohere_command': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""Cohere Command parser.\n\nUses ``cohere_melody`` as a stateful parser filter.\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom collections.abc import Mapping, Sequence\nfrom typing import TYPE_CHECKING, Any, NamedTuple, TypedDict, TypeGuard\n\nimport regex as re\nimport xgrammar as xgr\n\ntry:\n    from cohere_melody import (\n        AccumulatedToolCall,\n        FilterAggregatedResult,\n        PyFilter,\n        PyFilterOptions,\n    )\nexcept ImportError as e:\n    raise ImportError(\n        "The Cohere Command parser requires the `cohere_melody` package. "\n        "Install it with:\\n    pip install \'cohere-melody>=0.14.0\'"\n    ) from e\n\nfrom vllm.entrypoints.cohere.cohere_chat_message import (\n    Citation,\n    CitationSource,\n    CohereDeltaMessage,\n)\nfrom vllm.entrypoints.generate.base.protocol import (\n    AnyResponseFormat,\n    DeltaFunctionCall,\n    DeltaMessage,\n    DeltaToolCall,\n    FunctionCall,\n)\nfrom vllm.entrypoints.openai.chat_completion.protocol import ChatCompletionRequest\nfrom vllm.parser.abstract_parser import DelegatingParser\nfrom vllm.reasoning.cohere_command_reasoning_parser import (\n    BaseCohereCommandReasoningParser,\n)\nfrom vllm.renderers.cohere import POSITION_TO_SOURCE_KEY\nfrom vllm.sampling_params import StructuredOutputsParams\nfrom vllm.tool_parsers.cohere_command_tool_parser import BaseCohereCommandToolParser\n\nif TYPE_CHECKING:\n    # Declared in melody\'s stub only; not exported at runtime.\n    from cohere_melody import FilterCitation, Source\n\n    from vllm.config import ModelConfig\n    from vllm.entrypoints.openai.responses.protocol import ResponsesRequest\n    from vllm.tokenizers import TokenizerLike\n    from vllm.tool_parsers.utils import Tool\n\nPositionToSource = Mapping[tuple[int, int], CitationSource]\n\n\nclass CohereTagRegistry(NamedTuple):\n    """A single ``structural_tag`` trigger / end pair (``begin`` uses ``trigger``)."""\n\n    trigger: str\n    end: str\n\n\nclass CohereTagStyle(NamedTuple):\n    """The structural tags style for a given model architecture.\n\n    ``json_tags`` lists every JSON-schema wrapper the model may emit (MOE uses\n    both response and text delimiters). ``tools`` is the tool-call wrapper.\n    """\n\n    json_tags: tuple[CohereTagRegistry, ...]\n    tools: CohereTagRegistry\n\n\nclass CohereNormalizedTool(TypedDict):\n    """A tool definition normalized to the shape ``collect_tool_schema`` expects.\n\n    ``parameters`` is a JSON Schema object (possibly empty) describing the tool\'s\n    call signature.\n    """\n\n    name: str\n    parameters: dict[str, Any]\n\n\nCOMMAND_A_TOOLS_TAG = CohereTagRegistry(\n    trigger="<|START_ACTION|>",\n    end="<|END_ACTION|>",\n)\nCOMMAND_A_JSON_TAG = CohereTagRegistry(\n    trigger="<|START_RESPONSE|>",\n    end="<|END_RESPONSE|>",\n)\nCOMMAND_A_PLUS_JSON_TAG = CohereTagRegistry(\n    trigger="<|START_TEXT|>",\n    end="<|END_TEXT|>",\n)\n\nMODEL_TO_TAG_STYLE: dict[str, CohereTagStyle] = {\n    "Cohere2ForCausalLM": CohereTagStyle(\n        json_tags=(COMMAND_A_JSON_TAG,),\n        tools=COMMAND_A_TOOLS_TAG,\n    ),\n    "Cohere2VisionForConditionalGeneration": CohereTagStyle(\n        json_tags=(COMMAND_A_JSON_TAG, COMMAND_A_PLUS_JSON_TAG),\n        tools=COMMAND_A_TOOLS_TAG,\n    ),\n    "Cohere2MoeForCausalLM": CohereTagStyle(\n        json_tags=(COMMAND_A_JSON_TAG, COMMAND_A_PLUS_JSON_TAG),\n        tools=COMMAND_A_TOOLS_TAG,\n    ),\n}\n\n\ndef collect_tool_schema(tool_schema: list[CohereNormalizedTool]) -> str:\n    """Build an xgrammar EBNF grammar that matches a JSON array of tool calls.\n\n    The grammar shape is architecture-independent; callers are responsible for\n    wrapping it in the correct structural tag (see ``CohereTagStyle.tools``).\n    """\n    tool_dictionary: dict[str, str] = {}\n    for tool in tool_schema:\n        tool_name = tool["name"]\n        tool_parameters = json.dumps(tool["parameters"])\n        json_schema = f"""{{\n                        "type": "object",\n                        "properties": {{\n                            "tool_call_id": {{\n                                "type": "string",\n                                "pattern": "^[0-9]+$"\n                            }},\n                            "tool_name": {{\n                                "type": "string",\n                                "const": "{tool_name}"\n                            }},\n                            "parameters": {tool_parameters}\n                            }}\n                            }}"""\n        tool_grammar = str(xgr.Grammar.from_json_schema(json_schema))\n        for match in re.findall(r"\\b(\\w+)\\s*::=", tool_grammar):\n            tool_grammar = re.sub(\n                rf"\\b{re.escape(match)}\\b", tool_name + match, tool_grammar\n            )\n        tool_dictionary[tool_name] = f"{tool_name} ::= {tool_name}root\\n{tool_grammar}"\n    # Emitted grammar shape:\n    #   root  ::= tools\n    #   tools ::= ws "[" ws tool (ws "," ws tool)* ws "]" ws\n    #   ws    ::= (" " | "\\t" | "\\n")*\n    #   tool  ::= <tool_a> | <tool_b> | ...         (one alternative per input)\n    #   <tool_x>     ::= <tool_x>root               (per-tool xgrammar rules)\n    #   <tool_x>root ::= ...                        (from xgr.Grammar.from_json_schema)\n    tool_alternatives = "tool ::= " + " | ".join(tool_dictionary.keys())\n    tool_rules = "\\n    ".join(tool_dictionary.values())\n    grammar = f"""root ::= tools\n    tools ::= ws "[" ws tool (ws "," ws tool)* ws "]" ws\n    ws    ::= (" " | "\\\\t" | "\\\\n")*\n    {tool_alternatives}\n    {tool_rules}\n    """\n    return grammar\n\n\ndef _tool_definitions_to_schema_list(\n    tools: str | list[Any],\n) -> list[CohereNormalizedTool]:\n    """\n    Build the list of ``CohereNormalizedTool`` dicts expected by\n    ``collect_tool_schema``.\n\n    Accepts:\n    - JSON string\n    - list of dicts with top-level ``name`` / ``parameters``\n    - list of Chat Completions-style ``{"type": "function", "function": {...}}``\n    - list of Pydantic models with ``model_dump()``\n    """\n    if isinstance(tools, str):\n        try:\n            parsed = json.loads(tools)\n        except json.JSONDecodeError:\n            return []\n        if not isinstance(parsed, list):\n            return []\n    else:\n        parsed = list(tools)\n\n    out: list[CohereNormalizedTool] = []\n    for raw in parsed:\n        t = raw.model_dump() if hasattr(raw, "model_dump") else raw\n        if not isinstance(t, dict):\n            continue\n        # Unwrap Chat Completions\' ``{"type": "function", "function": {...}}``\n        # shape; otherwise take the dict as-is.\n        if t.get("type") == "function" and isinstance(t.get("function"), dict):\n            t = t["function"]\n        name = t.get("name")\n        if not isinstance(name, str):\n            continue\n        params = t.get("parameters")\n        out.append(\n            CohereNormalizedTool(\n                name=name,\n                parameters=params if isinstance(params, dict) else {},\n            )\n        )\n    return out\n\n\ndef _has_effective_tools(\n    tools: str | list[Any] | None,\n) -> TypeGuard[str | list[Any]]:\n    """\n    True when ``tools`` contains at least one tool definition to convert.\n\n    ``ResponsesRequest`` defaults ``tools`` to ``[]``; ``ChatCompletionRequest``\n    uses ``None``. Both mean "no tools" here. Strings (e.g. a JSON blob) are\n    treated as effective only when non-blank.\n    """\n    if tools is None:\n        return False\n    if isinstance(tools, str):\n        return bool(tools.strip())\n    return len(tools) > 0\n\n\n# Builder: produces vLLM response_format in xgrammar\'s canonical format.\n# See xgrammar docs: type "structural_tag" with "format" = triggered_tags\n# and tag content type = json_schema | grammar.\ndef convert_schema_to_structural_tags(\n    schema: dict | None = None,\n    tools: str | list[Any] | None = None,\n    model_architecture: str | None = None,\n) -> str | None:\n    """\n    Returns a response_format string accepted by xgrammar\'s structural tag format.\n    Uses the canonical shape: {"type": "structural_tag", "format": {...}} with\n    format.type "triggered_tags" and tag content type "json_schema" or "grammar".\n\n    Callers that are not on an engine path (e.g. the reasoning parser) must pass\n    ``model_architecture`` explicitly.\n    """\n    if model_architecture is None or model_architecture not in MODEL_TO_TAG_STYLE:\n        return None\n    style = MODEL_TO_TAG_STYLE[model_architecture]\n\n    tags: list[dict] = []\n    triggers: list[str] = []\n\n    def _add_tag(tag: CohereTagRegistry, content: dict) -> None:\n        tags.append({"begin": tag.trigger, "content": content, "end": tag.end})\n        triggers.append(tag.trigger)\n\n    if schema is not None:\n        # One structural tag per JSON wrapper (e.g. MOE: response + text).\n        # Same for schema-only and "tools plus JSON mode" (North: schema when\n        # the model does not call tools).\n        for jt in style.json_tags:\n            _add_tag(jt, {"type": "json_schema", "json_schema": schema})\n\n    if _has_effective_tools(tools):\n        # ``tools`` may be a JSON string (poseidon / RESPONSE_FORMAT_TOOL_DEFINITIONS)\n        # or a list (Chat Completions ``request.tools`` as Pydantic models or dicts).\n        tool_schema_list = _tool_definitions_to_schema_list(tools)\n        if not tool_schema_list:\n            raise ValueError(\n                "No valid tool definitions could be parsed from the request for "\n                "structural tag conversion."\n            )\n        tool_grammar = collect_tool_schema(tool_schema_list)\n        _add_tag(style.tools, {"type": "grammar", "grammar": tool_grammar})\n\n    if not tags:\n        return None\n    return json.dumps(\n        {\n            "type": "structural_tag",\n            "format": {\n                "type": "triggered_tags",\n                "triggers": triggers,\n                "tags": tags,\n            },\n        }\n    )\n\n\ndef _response_format_type(\n    response_format: AnyResponseFormat | dict | None,\n) -> str | None:\n    if response_format is None:\n        return None\n    if isinstance(response_format, dict):\n        t = response_format.get("type")\n        return t if isinstance(t, str) else None\n    return response_format.type\n\n\ndef _maybe_parse_json_dict(value: Any) -> dict | None:\n    """If value is a JSON string, parse to dict; otherwise require dict."""\n    if isinstance(value, dict):\n        return value\n    if isinstance(value, str):\n        try:\n            parsed = json.loads(value)\n        except (TypeError, json.JSONDecodeError):\n            return None\n        return parsed if isinstance(parsed, dict) else None\n    return None\n\n\ndef _unwrap_nested_schema(candidate: Any) -> dict | None:\n    """Return ``candidate`` as a dict, unwrapping a nested ``schema`` if present.\n\n    Returns ``None`` if ``candidate`` is not (and cannot be parsed into) a dict.\n    """\n    cand = _maybe_parse_json_dict(candidate)\n    if not isinstance(cand, dict):\n        return None\n    nested = cand.get("schema")\n    return nested if isinstance(nested, dict) else cand\n\n\ndef _schema_from_json_schema_field(js_wr: Any) -> dict | None:\n    """\n    Extract the JSON Schema object from Chat Completions ``json_schema`` payload.\n\n    Accepts:\n    - ``JsonSchemaResponseFormat`` (Pydantic) with ``schema`` / ``json_schema`` field\n    - dict in OpenAI shape ``{"name": ..., "schema": {...}}``\n    - dict with ``json_schema`` key holding either the schema or a nested wrapper\n    - dict that is already a JSON Schema document (some clients omit the wrapper)\n    - JSON strings for any of the above\n    """\n    if js_wr is None:\n        return None\n\n    parsed_wr = _maybe_parse_json_dict(js_wr)\n    if parsed_wr is not None:\n        js_wr = parsed_wr\n\n    if hasattr(js_wr, "model_dump"):\n        for by_alias in (True, False):\n            try:\n                data = js_wr.model_dump(by_alias=by_alias, exclude_none=False)\n            except TypeError:\n                data = js_wr.model_dump(by_alias=by_alias)\n            out = _unwrap_nested_schema(data.get("schema") or data.get("json_schema"))\n            if out is not None:\n                return out\n        inner_attr = getattr(js_wr, "json_schema", None)\n        return inner_attr if isinstance(inner_attr, dict) else None\n\n    if isinstance(js_wr, dict):\n        for key in ("schema", "json_schema"):\n            out = _unwrap_nested_schema(js_wr.get(key))\n            if out is not None:\n                return out\n        return js_wr\n\n    return None\n\n\ndef _schema_dict_from_chat_response_format(\n    rf: AnyResponseFormat | dict | None,\n) -> dict | None:\n    """JSON schema dict from Chat Completions ``request.response_format`` only."""\n    if rf is None:\n        return None\n    rf_type = _response_format_type(rf)\n    if rf_type == "json_object":\n        return {"type": "object"}\n    if rf_type != "json_schema":\n        return None\n    js_wr = (\n        rf.get("json_schema")\n        if isinstance(rf, dict)\n        else getattr(rf, "json_schema", None)\n    )\n    return _schema_from_json_schema_field(js_wr)\n\n\ndef _schema_dict_from_structured_outputs(\n    so: StructuredOutputsParams | None,\n) -> dict | None:\n    """Schema dict from ``structured_outputs`` (``json`` / ``json_object``).\n\n    Same unwrapping as ``json_schema``. ``json`` is expected to be ``str`` or\n    ``dict`` (enforced by ``StructuredOutputsParams`` / request models); other\n    types raise ``ValueError`` only if a caller bypasses that validation.\n    """\n    if so is None:\n        return None\n    if so.json_object:\n        return {"type": "object"}\n    raw: Any = so.json\n    if raw is None:\n        return None\n\n    if hasattr(raw, "model_dump"):\n        out = _schema_from_json_schema_field(raw)\n        if out is None:\n            raise ValueError(\n                "structured_outputs.json model has no extractable JSON Schema."\n            )\n        return out\n\n    if isinstance(raw, str):\n        if not raw.strip():\n            raise ValueError("structured_outputs.json cannot be empty.")\n        try:\n            raw = json.loads(raw)\n        except json.JSONDecodeError as e:\n            raise ValueError("structured_outputs.json must be valid JSON.") from e\n        if not isinstance(raw, dict):\n            raise ValueError("structured_outputs.json must decode to a JSON object.")\n\n    if isinstance(raw, Mapping):\n        body = raw if isinstance(raw, dict) else dict(raw)\n        return _schema_from_json_schema_field(body) or body\n\n    raise ValueError(\n        f"structured_outputs.json has unsupported type {type(raw).__name__}."\n    )\n\n\ndef _melody_sources_to_vllm(\n    sources: list[Source], position_to_source: PositionToSource | None\n) -> list[CitationSource]:\n    """Resolve melody ``Source`` addresses into :class:`CitationSource` objects.\n\n    Melody reports each source as ``(tool_call_index, tool_result_indices)``.\n    ``position_to_source`` is built by\n    :meth:`vllm.entrypoints.cohere.serving.CohereServingChatV2._build_position_to_source`\n    and forwarded through ``chat_template_kwargs``; each index fans out to one\n    resolved source, and unresolved positions are skipped. Without a map (a\n    request that did not come through the Cohere v2 handler) every source is\n    dropped and the serving layer discards the citation at wire-coercion time.\n    """\n    if not position_to_source:\n        return []\n    out: list[CitationSource] = []\n    for source in sources:\n        for idx in source.tool_result_indices:\n            info = position_to_source.get((source.tool_call_index, idx))\n            if info is not None:\n                out.append(info)\n    return out\n\n\ndef _melody_citations_to_vllm(\n    citations: list[FilterCitation], position_to_source: PositionToSource | None\n) -> list[Citation] | None:\n    """Convert melody ``FilterCitation`` objects into :class:`Citation`.\n\n    Citations whose sources all fail to resolve are still returned with\n    ``sources=[]``; the serving layer drops them so the fail-closed policy\n    lives in one place.\n    """\n    if not citations:\n        return None\n    return [\n        Citation(\n            start=c.start_index,\n            end=c.end_index,\n            text=c.text,\n            sources=_melody_sources_to_vllm(c.sources, position_to_source),\n            type="THINKING_CONTENT" if c.is_thinking else "TEXT_CONTENT",\n        )\n        for c in citations\n    ]\n\n\nclass CohereCommandParser(DelegatingParser):\n    def __init__(\n        self,\n        tokenizer: TokenizerLike,\n        tools: list[Tool] | None = None,\n        *args,\n        model_config: ModelConfig | None = None,\n        **kwargs,\n    ):\n        super().__init__(tokenizer, tools, *args, model_config=model_config, **kwargs)\n        self._model_config = model_config\n        self.start_token_id = tokenizer.convert_tokens_to_ids("<|START_THINKING|>")\n        self.end_token_id = tokenizer.convert_tokens_to_ids("<|END_THINKING|>")\n        shim = self._reasoning_parser or self._tool_parser\n        assert isinstance(\n            shim, (BaseCohereCommandReasoningParser, BaseCohereCommandToolParser)\n        )\n        options = getattr(PyFilterOptions(), shim.melody_preset)()\n        self._streaming = PyFilter(options)\n        self._unary = PyFilter(options)\n        # Citations from the most recent ``parse`` call, surfaced on\n        # ``CohereChatMessage`` by ``CohereServingChatV2``.\n        self.last_unary_citations: list[Citation] | None = None\n        # Melody may emit a tool-call id before the function name; hold it until\n        # the first name delta so clients receive both together.\n        self._pending_tool_ids: dict[int, str] = {}\n        ctk = kwargs.get("chat_template_kwargs") or {}\n        raw_map = ctk.get(POSITION_TO_SOURCE_KEY)\n        self._position_to_source: PositionToSource | None = (\n            raw_map if isinstance(raw_map, Mapping) else None\n        )\n\n    def adjust_request(\n        self, request: ChatCompletionRequest | ResponsesRequest\n    ) -> ChatCompletionRequest | ResponsesRequest:\n        # keep special tokens to ensure melody can correctly identify boundaries.\n        request.skip_special_tokens = False\n        request = self._apply_structural_tags(request)\n        return super().adjust_request(request)\n\n    def _apply_structural_tags(\n        self, request: ChatCompletionRequest | ResponsesRequest\n    ) -> ChatCompletionRequest | ResponsesRequest:\n        """Fold ``tools`` and any JSON schema into a Cohere ``structural_tag``."""\n        so = request.structured_outputs\n        if so is not None and so.structural_tag:\n            return request\n        # Schema: prefer ``response_format`` (OpenAI Chat Completions), then\n        # ``structured_outputs.json`` / ``json_object`` (vLLM direct). Tools stay\n        # on ``request.tools``.\n        rf = (\n            request.response_format\n            if isinstance(request, ChatCompletionRequest)\n            else None\n        )\n        if rf is not None and _response_format_type(rf) == "structural_tag":\n            return request\n        model_architecture = (\n            self._model_config.architecture if self._model_config is not None else None\n        )\n        tools = request.tools\n        # ``response_format`` wins if both it and ``structured_outputs`` supply JSON.\n        schema = _schema_dict_from_chat_response_format(rf)\n        if schema is None:\n            schema = _schema_dict_from_structured_outputs(so)\n        if schema is None and not _has_effective_tools(tools):\n            return request\n        if model_architecture is None:\n            return request\n        result = convert_schema_to_structural_tags(\n            schema=schema,\n            tools=tools,\n            model_architecture=model_architecture,\n        )\n        if result is None:\n            # Unsupported architectures are not in ``MODEL_TO_TAG_STYLE``.\n            raise ValueError(\n                "Failed to build structural_tag guided decoding constraints from "\n                "this request\'s JSON schema and/or tools. The configured model "\n                f"architecture ({model_architecture!r}) does not support Cohere "\n                "command structural tags, or the schema cannot be expressed in "\n                "that format."\n            )\n        request.structured_outputs = StructuredOutputsParams(structural_tag=result)\n        # Folded JSON constraints into ``structural_tag``; drop ``response_format``\n        # when it was the source so ``to_sampling_params`` does not also set ``json`` /\n        # ``json_object`` (mutually exclusive in ``StructuredOutputsParams``).\n        if isinstance(request, ChatCompletionRequest) and rf is not None:\n            rf_type = _response_format_type(rf)\n            if rf_type in ("json_schema", "json_object"):\n                request.response_format = None\n        return request\n\n    def count_reasoning_tokens(self, token_ids: Sequence[int]) -> int:\n        count = 0\n        depth = 0\n        for token_id in token_ids:\n            if token_id == self.start_token_id:\n                depth += 1\n                continue\n            if token_id == self.end_token_id:\n                if depth > 0:\n                    depth -= 1\n                continue\n            if depth > 0:\n                count += 1\n        return count\n\n    def parse(\n        self,\n        model_output: str,\n        request: ChatCompletionRequest | ResponsesRequest,\n        enable_auto_tools: bool = False,\n        model_output_token_ids: Sequence[int] = (),\n    ) -> tuple[str | None, str | None, list[FunctionCall] | None]:\n        result = self._unary.process_full_text(model_output)\n        self.last_unary_citations = _melody_citations_to_vllm(\n            result.citations, self._position_to_source\n        )\n        tool_calls: list[FunctionCall] | None = None\n        if self._tools_allowed(request):\n            tool_calls = [\n                FunctionCall(id=tc.id, name=tc.name, arguments=tc.arguments)\n                for tc in result.tool_calls\n            ] or None\n        return result.reasoning, result.content, tool_calls\n\n    def parse_delta(\n        self,\n        delta_text: str,\n        delta_token_ids: list[int],\n        request: ChatCompletionRequest | ResponsesRequest,\n        prompt_token_ids: list[int] | None = None,\n        *,\n        finished: bool,\n    ) -> DeltaMessage | None:\n        results = [self._streaming.write_decoded(delta_text)]\n        if finished:\n            results.append(self._streaming.flush_partials())\n        return self._to_delta(results, request)\n\n    def _tools_allowed(self, request: ChatCompletionRequest | ResponsesRequest) -> bool:\n        return self._tool_parser is not None and request.tool_choice != "none"\n\n    def _to_delta(\n        self,\n        results: list[FilterAggregatedResult],\n        request: ChatCompletionRequest | ResponsesRequest,\n    ) -> CohereDeltaMessage | None:\n        content = self._join(r.content for r in results)\n        reasoning = (\n            self._join(r.reasoning for r in results)\n            if request.include_reasoning\n            else None\n        )\n        tool_calls: list[DeltaToolCall] = []\n        citations: list[Citation] = []\n        for result in results:\n            if result.tool_calls and self._tools_allowed(request):\n                tool_calls.extend(self._tool_call_deltas(result.tool_calls))\n            citations.extend(\n                _melody_citations_to_vllm(result.citations, self._position_to_source)\n                or []\n            )\n        if not (content or reasoning or tool_calls or citations):\n            return None\n        # ``CohereDeltaMessage`` carries citations to the wire via\n        # ``SerializeAsAny[DeltaMessage]``; it drops the field when unset so the\n        # shape matches a plain ``DeltaMessage``.\n        message = CohereDeltaMessage()\n        if content is not None:\n            message.content = content\n        if reasoning is not None:\n            message.reasoning = reasoning\n        if tool_calls:\n            message.tool_calls = tool_calls\n        if citations:\n            message.citations = citations\n        return message\n\n    @staticmethod\n    def _join(parts: Any) -> str | None:\n        present = [p for p in parts if p is not None]\n        return "".join(present) if present else None\n\n    def _tool_call_deltas(\n        self, melody_tool_calls: list[AccumulatedToolCall]\n    ) -> list[DeltaToolCall]:\n        tool_calls: list[DeltaToolCall] = []\n        for tc in melody_tool_calls:\n            name = tc.name or None\n            arguments = tc.arguments or None\n            if tc.id:\n                self._pending_tool_ids[tc.index] = tc.id\n            # Empty strings are melody streaming placeholders; skip fragments\n            # that carry neither a name nor argument text.\n            if name is None and arguments is None:\n                continue\n            function = DeltaFunctionCall()\n            if name is not None:\n                function.name = name\n            if arguments is not None:\n                function.arguments = arguments\n            delta = DeltaToolCall(index=tc.index, function=function)\n            if name is not None:\n                resolved_id = tc.id or self._pending_tool_ids.pop(tc.index, None)\n                if resolved_id is not None:\n                    delta.id = resolved_id\n                delta.type = "function"\n            tool_calls.append(delta)\n        return tool_calls\n', False), 'vllm.parser.metrics': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""Prometheus metrics for the parsers."""\n\nfrom __future__ import annotations\n\nfrom enum import Enum\nfrom itertools import product\nfrom typing import cast\n\nfrom prometheus_client import REGISTRY, Counter\n\n_model_name: str | None = None\n\n_TOOL_CALL_PARSER_INVOCATIONS_TOTAL = "vllm:tool_call_parser_invocations_total"\n_tool_call_parser_invocations: Counter | None = None\n\n\nclass ToolCallOutcome(Enum):\n    TOOL_CALL = "tool_call"\n    NO_TOOL_CALL = "no_tool_call"\n\n\nclass RequestType(Enum):\n    CHAT_COMPLETIONS = "chat_completions"\n    RESPONSES = "responses"\n    OTHER = "other"\n\n\ndef init_parser_metrics(*, model_name: str) -> None:\n    """Lazily register parser metrics and cache the shared model label."""\n    global _model_name\n    _model_name = model_name\n\n    global _tool_call_parser_invocations\n    try:\n        _tool_call_parser_invocations = Counter(\n            name=_TOOL_CALL_PARSER_INVOCATIONS_TOTAL,\n            documentation=(\n                "Total number of ToolParser invocations. "\n                "Non-streaming increments once per choice; "\n                "streaming increments once per delta."\n            ),\n            labelnames=["model_name", "mode", "outcome", "request_type"],\n        )\n    except ValueError:\n        _tool_call_parser_invocations = cast(\n            Counter,\n            REGISTRY._names_to_collectors[_TOOL_CALL_PARSER_INVOCATIONS_TOTAL],\n        )\n\n    for mode, outcome, request_type in product(\n        ("streaming", "non_streaming"),\n        ToolCallOutcome,\n        RequestType,\n    ):\n        _tool_call_parser_invocations.labels(\n            model_name=_model_name,\n            mode=mode,\n            outcome=outcome.value,\n            request_type=request_type.value,\n        )\n\n\ndef record_tool_parser_invocation(\n    *,\n    is_tool_called: bool | Exception,\n    is_streaming: bool,\n    request: object,\n) -> None:\n    """Increment the tool-call parser invocation counter when registered.\n    Currently parser failures are treated as no tool calls.\n\n    TODO: To accurately track parser failures, add a new ToolCallOutcome and\n    more importantly, ensure exceptions are propagated out of the ToolParsers\n    instead of being caught internally. This would require going through\n    ToolParser implementation on a case-by-case basis.\n    """\n    if _tool_call_parser_invocations is None:\n        return\n\n    from vllm.entrypoints.openai.chat_completion.protocol import ChatCompletionRequest\n    from vllm.entrypoints.openai.responses.protocol import ResponsesRequest\n\n    match request:\n        case ChatCompletionRequest():\n            request_type = RequestType.CHAT_COMPLETIONS\n        case ResponsesRequest():\n            request_type = RequestType.RESPONSES\n        case _:\n            request_type = RequestType.OTHER\n\n    match is_tool_called:\n        case bool():\n            outcome = (\n                ToolCallOutcome.TOOL_CALL\n                if is_tool_called\n                else ToolCallOutcome.NO_TOOL_CALL\n            )\n        case _:\n            outcome = ToolCallOutcome.NO_TOOL_CALL\n\n    _tool_call_parser_invocations.labels(\n        model_name=_model_name,\n        mode="streaming" if is_streaming else "non_streaming",\n        outcome=outcome.value,\n        request_type=request_type.value,\n    ).inc()\n', False), 'vllm.parser.mistral': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n\nfrom __future__ import annotations\n\nimport functools\nimport json\nfrom collections.abc import Sequence\nfrom enum import Enum, auto\nfrom random import choices\nfrom string import ascii_letters, digits\nfrom typing import TYPE_CHECKING, Any, Literal\n\nimport ijson\nimport regex as re\nfrom mistral_common.protocol.instruct.tool_calls import (\n    NamedToolChoice as MistralNamedToolChoice,\n)\nfrom mistral_common.protocol.instruct.tool_calls import (\n    Tool as MistralTool,\n)\nfrom mistral_common.protocol.instruct.tool_calls import (\n    ToolChoice as MistralToolChoice,\n)\nfrom mistral_common.protocol.instruct.tool_calls import (\n    ToolChoiceEnum as MistralToolChoiceEnum,\n)\nfrom mistral_common.tokens.tokenizers.base import SpecialTokens\nfrom pydantic import Field\n\nfrom vllm.entrypoints.generate.base.protocol import (\n    DeltaFunctionCall,\n    DeltaMessage,\n    DeltaToolCall,\n    ExtractedToolCallInformation,\n    FunctionCall,\n    ToolCall,\n)\nfrom vllm.entrypoints.openai.chat_completion.protocol import (\n    ChatCompletionNamedToolChoiceParam,\n)\nfrom vllm.entrypoints.openai.responses.protocol import ResponsesRequest\nfrom vllm.logger import init_logger\nfrom vllm.parser.engine.events import EventType\nfrom vllm.parser.engine.parser_engine import ParserEngine\nfrom vllm.parser.engine.parser_engine_config import (\n    ParserEngineConfig,\n    ParserState,\n    Transition,\n)\nfrom vllm.sampling_params import StructuredOutputsParams\nfrom vllm.utils.mistral import is_mistral_tokenizer\n\nif TYPE_CHECKING:\n    from vllm.entrypoints.openai.chat_completion.protocol import (\n        ChatCompletionRequest,\n    )\n    from vllm.parser.engine.events import SemanticEvent\n    from vllm.parser.engine.parser_engine import ToolCallSlot\n    from vllm.tokenizers import TokenizerLike\n    from vllm.tool_parsers.abstract_tool_parser import Tool\n\nlogger = init_logger(__name__)\n\n_ALPHANUMERIC = ascii_letters + digits\n_DEFAULT_JSON_SCHEMA: dict[str, Any] = {\n    "anyOf": [{"type": "object"}, {"type": "array"}]\n}\n\n# Special token strings as emitted/decoded by MistralTokenizer.\n_TOOL_CALLS = SpecialTokens.tool_calls.value\n_ARGS = SpecialTokens.args.value\n_THINK_START_SPECIAL = SpecialTokens.begin_think.value\n_THINK_END_SPECIAL = SpecialTokens.end_think.value\n\n# Plain-text reasoning markers used by v11 tokenizers.\n_THINK_START_TEXT = "<think>"\n_THINK_END_TEXT = "</think>"\n\n_OPEN_BRACE = "{"\n\n\nclass StreamingState(Enum):\n    """Streaming parsing state for pre-v11 tool call extraction."""\n\n    WAITING_FOR_TOOL_START = auto()\n    WAITING_FOR_TOOL_KEY = auto()\n    PARSING_NAME = auto()\n    PARSING_NAME_COMPLETED = auto()\n    WAITING_FOR_ARGUMENTS_START = auto()\n    PARSING_ARGUMENTS = auto()\n    PARSING_ARGUMENTS_COMPLETED = auto()\n    TOOL_COMPLETE = auto()\n    ALL_TOOLS_COMPLETE = auto()\n\n\nclass MistralToolCall(ToolCall):\n    """ToolCall with a Mistral-compatible random alphanumeric id."""\n\n    id: str = Field(default_factory=lambda: MistralToolCall.generate_random_id())\n\n    @staticmethod\n    def generate_random_id() -> str:\n        # Mistral Tool Call Ids must be alphanumeric with a length of 9.\n        # https://github.com/mistralai/mistral-common/blob/21ee9f6cee3441e9bb1e6ed2d10173f90bd9b94b/src/mistral_common/protocol/instruct/validator.py#L299\n        return "".join(choices(_ALPHANUMERIC, k=9))\n\n    @staticmethod\n    def is_valid_id(id: str) -> bool:\n        return id.isalnum() and len(id) == 9\n\n\ndef _is_pre_v11_tokeniser(model_tokenizer: TokenizerLike) -> bool:\n    if is_mistral_tokenizer(model_tokenizer):\n        return model_tokenizer.version < 11\n    vocab: dict[str, int] = getattr(model_tokenizer, "get_vocab", lambda: {})()\n    return _ARGS not in vocab\n\n\n@functools.cache\ndef mistral_config(\n    *,\n    reasoning_encoding: Literal["special_token", "text", "none"],\n    name: str = "mistral",\n) -> ParserEngineConfig:\n    """Return a :class:`ParserEngineConfig` for the Mistral output format.\n\n    Args:\n        reasoning_encoding: Reasoning token format.\n            ``"special_token"`` – v13+ ``[THINK]``/``[/THINK]`` special\n            tokens placed in both ``terminals`` and ``token_id_terminals``.\n            ``"text"`` – v11 ``<think>``/``</think>`` plain text placed in\n            ``terminals`` only; no ``token_id_terminals`` for think tokens.\n            ``"none"`` – no reasoning support.\n        name: Name embedded in the returned config (used for debugging).\n\n    Returns:\n        A frozen :class:`ParserEngineConfig` with ``initial_state=CONTENT``.\n    """\n    if reasoning_encoding == "special_token":\n        think_start = _THINK_START_SPECIAL\n        think_end = _THINK_END_SPECIAL\n        reasoning_terminals: dict[str, str] = {\n            "THINK_START": think_start,\n            "THINK_END": think_end,\n        }\n        reasoning_token_id_terminals: dict[str, str] = {\n            "THINK_START": think_start,\n            "THINK_END": think_end,\n        }\n    elif reasoning_encoding == "text":\n        think_start = _THINK_START_TEXT\n        think_end = _THINK_END_TEXT\n        reasoning_terminals = {\n            "THINK_START": think_start,\n            "THINK_END": think_end,\n        }\n        # Text think markers have no token-id terminals.\n        reasoning_token_id_terminals = {}\n    else:\n        reasoning_terminals = {}\n        reasoning_token_id_terminals = {}\n\n    if reasoning_encoding != "none":\n        reasoning_transitions: dict[tuple[ParserState, str], Transition] = {\n            (ParserState.CONTENT, "THINK_START"): Transition(\n                ParserState.REASONING,\n                (),\n            ),\n            # Absorb a duplicate/re-emitted THINK_START inside reasoning.\n            (ParserState.REASONING, "THINK_START"): Transition(\n                ParserState.REASONING,\n                (),\n            ),\n            (ParserState.REASONING, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (EventType.REASONING_END,),\n            ),\n            # Absorb stray THINK_END that arrives after reasoning ended.\n            (ParserState.CONTENT, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            # [TOOL_CALLS] directly from reasoning implicitly ends it.\n            (ParserState.REASONING, "TOOL_CALLS"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.REASONING_END, EventType.TOOL_CALL_START),\n            ),\n        }\n    else:\n        reasoning_transitions = {}\n\n    return ParserEngineConfig(\n        name=name,\n        initial_state=ParserState.CONTENT,\n        wait_for_reasoning=reasoning_encoding != "none",\n        terminals={\n            **reasoning_terminals,\n            "TOOL_CALLS": _TOOL_CALLS,\n            "ARGS": _ARGS,\n            "OPEN_BRACE": _OPEN_BRACE,\n        },\n        token_id_terminals={\n            **reasoning_token_id_terminals,\n            "TOOL_CALLS": _TOOL_CALLS,\n            "ARGS": _ARGS,\n        },\n        transitions={\n            **reasoning_transitions,\n            # A tool call from content implicitly ends reasoning when enabled.\n            (ParserState.CONTENT, "TOOL_CALLS"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.REASONING_END, EventType.TOOL_CALL_START)\n                if reasoning_encoding != "none"\n                else (EventType.TOOL_CALL_START,),\n            ),\n            # NAME→ARGS via explicit [ARGS] separator (v11+): consumed, no events.\n            (ParserState.TOOL_NAME, "ARGS"): Transition(\n                ParserState.TOOL_ARGS,\n                (),\n            ),\n            # NAME→ARGS via "{": carried as ARG_VALUE_CHUNK so the opening\n            # brace lands in the JSON argument buffer (fallback for name{args}).\n            (ParserState.TOOL_NAME, "OPEN_BRACE"): Transition(\n                ParserState.TOOL_ARGS,\n                (EventType.ARG_VALUE_CHUNK,),\n            ),\n            # Parallel tool calls: next [TOOL_CALLS] ends current call.\n            (ParserState.TOOL_ARGS, "TOOL_CALLS"): Transition(\n                ParserState.TOOL_NAME,\n                (EventType.TOOL_CALL_END, EventType.TOOL_CALL_START),\n            ),\n        },\n        stream_arg_deltas=True,\n        tool_args_json=True,\n        strip_trailing_reasoning_whitespace=True,\n        drop_whitespace_only_content_before_tools=True,\n    )\n\n\nclass MistralParser(ParserEngine):\n    """Mistral parser: engine-based reasoning + ``[TOOL_CALLS]`` tool calls.\n\n    Reasoning encoding is auto-detected from the tokenizer:\n\n    - ``"special_token"`` – ``[THINK]`` present in vocab (v13+).\n    - ``"text"`` – tokenizer supports grammar but has no ``[THINK]`` (v11).\n    - ``"none"`` – no grammar support; reasoning disabled.\n\n    Tool calls use the ``[TOOL_CALLS]func_name{...}`` format.  The opening\n    ``{`` doubles as the NAME→ARGS separator and is included in the argument\n    buffer via an ``ARG_VALUE_CHUNK`` event on the transition (mirrors\n    kimi_k2, JSON args, `tool_args_json=True`).\n\n    When the tokenizer does not support grammar (``_reasoning_encoding ==\n    "none"``), the legacy ``[TOOL_CALLS]``-based extraction path is used\n    instead of the deoperatortive engine, handling both pre-v11 JSON-array and\n    v11+ ``funcname{args}`` formats.\n    """\n\n    def __init__(\n        self,\n        tokenizer: TokenizerLike,\n        tools: list[Tool] | None = None,\n        **kwargs,\n    ) -> None:\n        vocab = tokenizer.get_vocab()\n        self._reasoning_encoding: Literal["special_token", "text", "none"]\n        if _THINK_START_SPECIAL in vocab:\n            self._reasoning_encoding = "special_token"\n        elif getattr(tokenizer, "supports_grammar", False):\n            self._reasoning_encoding = "text"\n        else:\n            self._reasoning_encoding = "none"\n\n        kwargs.setdefault(\n            "parser_engine_config",\n            mistral_config(reasoning_encoding=self._reasoning_encoding),\n        )\n        super().__init__(tokenizer, tools, **kwargs)\n\n        self._tool_calls_token_id: int | None = self.vocab.get(_TOOL_CALLS)\n\n        # Tool calls use the legacy parser for all tokenizer versions;\n        # reasoning is handled by the engine.\n        self.bot_token: str = _TOOL_CALLS\n        self.bot_token_id: int | None = self._tool_calls_token_id\n        if self.bot_token_id is None:\n            raise RuntimeError(\n                "Mistral parser could not locate the tool call token in the tokenizer!"\n            )\n\n        # Legacy tool-call streaming state.\n        self.prev_tool_call_arr: list[dict[str, Any]] = []\n        self.current_tool_id: int = -1\n        self.streaming_state: StreamingState = StreamingState.WAITING_FOR_TOOL_START\n        self.tool_call_started: bool = False\n        self.current_tool_name: str | None = None\n        self.current_tool_mistral_id: str | None = None\n        self.starting_new_tool: bool = False\n        self.streamed_args_for_tool: list[str] = []\n        self._is_pre_v11: bool = _is_pre_v11_tokeniser(tokenizer)\n        self.parse_coro = None\n        if self._is_pre_v11:\n            self.parse_coro = ijson.parse_coro(\n                self.update_stream_state_pre_v11_tokenizer()\n            )\n        self.tool_call_regex = re.compile(r"\\[{.*}\\]", re.DOTALL)\n\n    def adjust_request(\n        self, request: ChatCompletionRequest | ResponsesRequest\n    ) -> ChatCompletionRequest | ResponsesRequest:\n        if not isinstance(request, ResponsesRequest) and request._grammar_from_parser:\n            return request\n        so_non_supported_attributes = [\n            "regex",\n            "choice",\n            "grammar",\n            # whitespace_pattern is not a constraint type but an option;\n            # Mistral grammar factory does not support it.\n            "whitespace_pattern",\n            "structural_tag",\n        ]\n        any_so_non_supported_active = request.structured_outputs is not None and any(\n            getattr(request.structured_outputs, attribute) is not None\n            for attribute in so_non_supported_attributes\n        )\n        response_format_non_supported_active = (\n            isinstance(request, ResponsesRequest)\n            or request.response_format is not None\n            and request.response_format.type == "structural_tag"\n        )\n\n        if (\n            not is_mistral_tokenizer(self.model_tokenizer)\n            or isinstance(request, ResponsesRequest)\n            or not self.model_tokenizer.supports_grammar\n            or any_so_non_supported_active\n            or response_format_non_supported_active\n        ):\n            request = super().adjust_request(request)\n            if request.tools and request.tool_choice != "none":\n                # Keep special tokens so the [TOOL_CALLS] marker\n                # survives for tool detection.\n                request.skip_special_tokens = False\n            # Inject a guided JSON schema for pre-v11 required/named tool choice\n            # so the model emits a well-formed bare JSON array instead of\n            # rambling. tool_choice forces a tool call, so a json_object /\n            # json_schema response_format is cleared here (the tool schema is\n            # the sole structured-output constraint), mirroring the base\n            # ToolParser; a structural_tag response_format is left untouched.\n            req_tool_choice = request.tool_choice\n            is_required_or_named = req_tool_choice == "required" or isinstance(\n                req_tool_choice, ChatCompletionNamedToolChoiceParam\n            )\n            response_format = getattr(request, "response_format", None)\n            response_format_overridable = response_format is None or (\n                response_format.type in ("text", "json_object", "json_schema")\n            )\n            # This runs only in the non-grammar (legacy) branch, so it covers\n            # both pre-v11 Mistral tokenizers and non-Mistral (e.g. HF-mode)\n            # tokenizers driving the Mistral tool parser. The remaining guards\n            # keep it off when the user supplied their own structured output.\n            if (\n                not isinstance(request, ResponsesRequest)\n                and request.tools\n                and request.structured_outputs is None\n                and is_required_or_named\n                and response_format_overridable\n            ):\n                schema = self._build_guided_schema_pre_v11(request)\n                if schema is not None:\n                    request.structured_outputs = StructuredOutputsParams(json=schema)\n                    request.response_format = None\n            return request\n\n        json_schema: dict[str, Any] | None = None\n        if request.structured_outputs is not None:\n            if request.structured_outputs.json_object is not None:\n                json_schema = _DEFAULT_JSON_SCHEMA\n            elif request.structured_outputs.json is not None:\n                if isinstance(request.structured_outputs.json, str):\n                    json_schema = json.loads(request.structured_outputs.json)\n                else:\n                    json_schema = request.structured_outputs.json\n            else:\n                raise ValueError(\n                    "Unsupported request.structured_outputs for MistralParser. "\n                    "Only `json` and `json_object` are supported."\n                )\n        elif (\n            request.response_format is not None\n            and request.response_format.type != "text"\n        ):\n            if request.response_format.type == "json_object":\n                json_schema = _DEFAULT_JSON_SCHEMA\n            elif request.response_format.type == "json_schema":\n                if request.response_format.json_schema is not None:\n                    json_schema = request.response_format.json_schema.json_schema\n                else:\n                    json_schema = _DEFAULT_JSON_SCHEMA\n            else:\n                raise ValueError(\n                    "MistralParser only accepts `text`, `json_object` or "\n                    f"`json_schema`, got {request.response_format=}"\n                )\n            request.response_format = None\n\n        grammar_factory = self.model_tokenizer.grammar_factory\n\n        # Rendering grammar is cached in mistral-common given tools, template and mode.\n        template = grammar_factory.select_jinja_template()\n\n        mistral_tools = (\n            [MistralTool.from_openai(tool.model_dump()) for tool in request.tools]\n            if request.tools is not None\n            else None\n        )\n\n        tool_choice: MistralToolChoice\n        match request.tool_choice:\n            case "none" | "auto" | "required":\n                tool_choice = MistralToolChoiceEnum(request.tool_choice)\n            case None:\n                tool_choice = MistralToolChoiceEnum.auto\n            # _ == Named tool choice\n            case _:\n                tool_choice = MistralNamedToolChoice.model_validate(\n                    {\n                        "type": "function",\n                        "function": {"name": request.tool_choice.function.name},\n                    }\n                )\n\n        match tool_choice, json_schema is not None:\n            case MistralToolChoiceEnum.none, True:\n                lark_grammar = grammar_factory.get_lark_for_json_schema(\n                    template=template, json_schema=json_schema\n                )\n            case _, _:\n                lark_grammar = grammar_factory.get_lark_from_jinja(\n                    template=template,\n                    mode=tool_choice,\n                    tools=mistral_tools,\n                    json_schema=json_schema,\n                    parallel_tool_calls=request.parallel_tool_calls,\n                    json_only=False,\n                )\n\n        request.structured_outputs = StructuredOutputsParams(grammar=lark_grammar)\n        request._grammar_from_parser = True\n        return request\n\n    def _build_guided_schema_pre_v11(\n        self,\n        request: ChatCompletionRequest,\n    ) -> dict[str, Any] | None:\n        """Build a guided JSON schema for pre-v11 required/named tool choice.\n\n        The schema enforces the Mistral-native array format\n        ``[{"name": ..., "arguments": {...}}]`` so the model emits a parseable\n        bare JSON array instead of free-form text.\n\n        Args:\n            request: The chat completion request carrying `tools` and\n                `tool_choice`.\n\n        Returns:\n            A JSON Schema dict, or ``None`` if the named tool is not found.\n        """\n        tool_choice = request.tool_choice\n        tools = request.tools or []\n        extra: dict[str, Any] = {}\n\n        if tool_choice == "required":\n            applicable_tools = tools\n        else:\n            # Named tool choice — restrict to the single requested tool.\n            assert isinstance(tool_choice, ChatCompletionNamedToolChoiceParam)\n            chosen_name = tool_choice.function.name\n            applicable_tools = [t for t in tools if t.function.name == chosen_name]\n            if not applicable_tools:\n                logger.warning(\n                    "Named tool %r not found in tools list; "\n                    "skipping guided schema injection.",\n                    chosen_name,\n                )\n                return None\n            extra["maxItems"] = 1\n\n        any_of = [\n            {\n                "type": "object",\n                "properties": {\n                    "name": {"type": "string", "enum": [tool.function.name]},\n                    "arguments": tool.function.parameters or {"type": "object"},\n                },\n                "required": ["name", "arguments"],\n            }\n            for tool in applicable_tools\n        ]\n\n        return {\n            "type": "array",\n            "minItems": 1,\n            **extra,\n            "items": {\n                "type": "object",\n                "anyOf": any_of,\n            },\n        }\n\n    def _ensure_tool_id(self, slot: ToolCallSlot, name: str) -> None:\n        """Assign a Mistral-compatible 9-char alphanumeric id to `slot`."""\n        if not slot.id:\n            slot.id = MistralToolCall.generate_random_id()\n\n    def extract_tool_calls_from_content(\n        self,\n        content: str,\n        request: ChatCompletionRequest,\n    ) -> ExtractedToolCallInformation:\n        if self._is_pre_v11:\n            return self._legacy_extract_tool_calls(content, request)\n        return super().extract_tool_calls_from_content(content, request)\n\n    def _legacy_extract_tool_calls(\n        self,\n        model_output: str,\n        request: ChatCompletionRequest | None,\n    ) -> ExtractedToolCallInformation:\n        """Pre-v11 non-streaming extraction.\n\n        Handles ``[TOOL_CALLS][{...}]`` and guided bare-array formats.\n        """\n        if request is None:\n            tool_choice = None\n            tools = None\n        else:\n            tool_choice = request.tool_choice\n            tools = request.tools\n\n        # tool_choice="none" with tools: never produce tool calls.\n        if tool_choice == "none" and tools:\n            return ExtractedToolCallInformation(\n                tools_called=False, tool_calls=[], content=model_output\n            )\n\n        content: str | None = None\n        if self.bot_token in model_output:\n            content_and_raw_tool_calls = model_output.split(self.bot_token)\n            content = content_and_raw_tool_calls[0]\n            raw_tool_calls = content_and_raw_tool_calls[1:]\n            # pre-v11: content[BOT] [{tool_call1},{tool_call2}]\n            if len(raw_tool_calls) != 1:\n                raise ValueError(\n                    "Only one BOT token should have been outputted, "\n                    f"but got {model_output}."\n                )\n            stringified_tool_calls = raw_tool_calls[0].strip()\n        elif tool_choice == "required" or isinstance(\n            tool_choice, ChatCompletionNamedToolChoiceParam\n        ):\n            # Guided bare-array output (no [TOOL_CALLS] marker).\n            stringified_tool_calls = model_output.strip()\n        else:\n            return ExtractedToolCallInformation(\n                tools_called=False, tool_calls=[], content=model_output\n            )\n\n        try:\n            # Use raw_decode to parse the first valid JSON value,\n            # ignoring trailing tokens the model may emit after\n            # the tool call array.\n            tool_calls, _ = json.JSONDecoder().raw_decode(stringified_tool_calls)\n        except json.JSONDecodeError:\n            try:\n                raw_tool_call = self.tool_call_regex.findall(stringified_tool_calls)[0]\n                tool_calls = json.loads(raw_tool_call)\n                tool_calls = [\n                    {\n                        "name": tool_call["name"],\n                        "arguments": json.dumps(\n                            tool_call.get("arguments", {}),\n                            ensure_ascii=False,\n                        ),\n                    }\n                    for tool_call in tool_calls\n                ]\n            except (IndexError, json.JSONDecodeError):\n                logger.exception("Error in extracting tool call from response.")\n                return ExtractedToolCallInformation(\n                    tools_called=False,\n                    tool_calls=[],\n                    content=stringified_tool_calls,\n                )\n        else:\n            tool_calls = [\n                {\n                    "name": tool_call["name"],\n                    "arguments": json.dumps(\n                        tool_call.get("arguments", {}),\n                        ensure_ascii=False,\n                    ),\n                }\n                for tool_call in tool_calls\n            ]\n\n        mistral_tool_calls: list[MistralToolCall] = [\n            MistralToolCall(\n                type="function",\n                function=FunctionCall(\n                    name=tool_call["name"],\n                    arguments=tool_call.get("arguments", "{}"),\n                ),\n            )\n            for tool_call in tool_calls\n        ]\n\n        return ExtractedToolCallInformation(\n            tools_called=True,\n            tool_calls=mistral_tool_calls,\n            content=content if content and content.strip() else None,\n        )\n\n    def extract_tool_calls_streaming(\n        self,\n        previous_text: str,\n        current_text: str,\n        delta_text: str,\n        previous_token_ids: Sequence[int],\n        current_token_ids: Sequence[int],\n        delta_token_ids: Sequence[int],\n        request: ChatCompletionRequest | ResponsesRequest,\n    ) -> DeltaMessage | None:\n        if not self._is_pre_v11:\n            return super().extract_tool_calls_streaming(\n                previous_text,\n                current_text,\n                delta_text,\n                previous_token_ids,\n                current_token_ids,\n                delta_token_ids,\n                request,\n            )\n        # Pre-v11: latch on [TOOL_CALLS] or on the first content of a guided\n        # required/named request (bare JSON array, no special token).\n        if self.bot_token_id in delta_token_ids or self.bot_token in delta_text:\n            self.tool_call_started = True\n        elif not self.tool_call_started and delta_text:\n            is_guided = request.tool_choice == "required" or isinstance(\n                request.tool_choice, ChatCompletionNamedToolChoiceParam\n            )\n            if is_guided:\n                self.tool_call_started = True\n        if not self.tool_call_started:\n            return DeltaMessage(content=delta_text)\n        try:\n            return self._extract_tool_calls_streaming_pre_v11_tokenizer(\n                delta_text=delta_text,\n                delta_token_ids=delta_token_ids,\n            )\n        except Exception:\n            logger.exception("Error trying to handle streaming tool call.")\n            return None\n\n    @ijson.coroutine\n    def update_stream_state_pre_v11_tokenizer(self):\n        while True:\n            (prefix, event, value) = yield\n\n            if prefix == "item" and event == "start_map":\n                self.streaming_state = StreamingState.WAITING_FOR_TOOL_KEY\n                self.starting_new_tool = True\n            if prefix == "item" and event == "map_key" and value == "name":\n                self.streaming_state = StreamingState.PARSING_NAME\n            if prefix == "item.name" and event == "string":\n                self.current_tool_name = value\n                self.streaming_state = StreamingState.PARSING_NAME_COMPLETED\n            if prefix == "item" and event == "map_key" and value == "arguments":\n                self.streaming_state = StreamingState.WAITING_FOR_ARGUMENTS_START\n            if prefix == "item.arguments" and event == "start_map":\n                self.streaming_state = StreamingState.PARSING_ARGUMENTS\n            if prefix == "item.arguments" and event == "end_map":\n                self.streaming_state = StreamingState.PARSING_ARGUMENTS_COMPLETED\n            if prefix == "item" and event == "end_map":\n                self.streaming_state = StreamingState.TOOL_COMPLETE\n            if prefix == "" and event == "end_array":\n                self.streaming_state = StreamingState.ALL_TOOLS_COMPLETE\n\n    def _extract_tool_calls_streaming_pre_v11_tokenizer(\n        self,\n        delta_text: str,\n        delta_token_ids: Sequence[int],\n    ) -> DeltaMessage | None:\n        """Extract tool calls for pre-v11 Mistral models.\n\n        Handles ``[TOOL_CALLS][{"name": "add", "arguments":{"a": 3.5}}]``.\n        """\n        assert self.parse_coro is not None\n        content = None\n        delta_tool_calls: list[DeltaToolCall] = []\n        current_tool_call: DeltaToolCall = DeltaToolCall(\n            index=self.current_tool_id, type="function"\n        )\n        current_tool_call_modified = False\n        if self.bot_token_id in delta_token_ids or self.bot_token in delta_text:\n            # this is the first tool call\n            if not delta_text.startswith(self.bot_token):\n                content = delta_text.split(self.bot_token)[0]\n            delta_text = "".join(delta_text.split(self.bot_token)[1:])\n\n        # ijson gives no text index per event, so split the delta manually\n        # to know where each event is emitted from.\n        while len(delta_text) > 0:\n            streaming_state_before_parse = self.streaming_state\n\n            if self.streaming_state == StreamingState.WAITING_FOR_TOOL_START:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_opening_curly_braces=1,\n                )\n            elif self.streaming_state == StreamingState.WAITING_FOR_TOOL_KEY:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_colon=1,\n                    stop_after_opening_curly_braces=1,\n                )\n            elif self.streaming_state == StreamingState.PARSING_NAME:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_comma=1,\n                    stop_after_closing_brackets=1,\n                )\n            elif self.streaming_state == StreamingState.WAITING_FOR_ARGUMENTS_START:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_opening_curly_braces=1,\n                )\n            elif self.streaming_state == StreamingState.PARSING_ARGUMENTS:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_closing_curly_braces=1,\n                )\n            elif self.streaming_state in [\n                StreamingState.PARSING_ARGUMENTS_COMPLETED,\n                StreamingState.PARSING_NAME_COMPLETED,\n            ]:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_closing_curly_braces=1,\n                    stop_after_closing_brackets=1,\n                )\n            elif self.streaming_state == StreamingState.TOOL_COMPLETE:\n                delta_to_be_parsed, delta_text = self._split_delta(\n                    delta_text=delta_text,\n                    stop_after_opening_curly_braces=1,\n                    stop_after_closing_brackets=1,\n                )\n            elif self.streaming_state == StreamingState.ALL_TOOLS_COMPLETE:\n                content = delta_text\n                delta_text = ""\n            else:\n                delta_to_be_parsed = delta_text\n                delta_text = ""\n\n            if self.streaming_state != StreamingState.ALL_TOOLS_COMPLETE:\n                self.parse_coro.send(delta_to_be_parsed.encode("utf-8"))\n\n            # start_map is the authoritative new-tool signal and survives\n            # batched deltas, unlike comparing pre/post streaming states.\n            if self.starting_new_tool:\n                self.starting_new_tool = False\n                if current_tool_call_modified:\n                    if self.current_tool_mistral_id is not None:\n                        current_tool_call.id = self.current_tool_mistral_id\n                        self.current_tool_mistral_id = None\n                    self._track_streamed_args_pre_v11(current_tool_call)\n                    delta_tool_calls.append(current_tool_call)\n                current_tool_call_modified = False\n                self.current_tool_id += 1\n                self.streamed_args_for_tool.append("")\n                self.prev_tool_call_arr.append({})\n                self.current_tool_mistral_id = MistralToolCall.generate_random_id()\n                current_tool_call = DeltaToolCall(\n                    index=self.current_tool_id,\n                    type="function",\n                )\n            if current_tool_call.function is None:\n                current_tool_call.function = DeltaFunctionCall()\n\n            if self.current_tool_name is not None:\n                current_tool_call_modified = True\n                current_tool_call.function.name = self.current_tool_name\n                self.prev_tool_call_arr[self.current_tool_id]["name"] = (\n                    self.current_tool_name\n                )\n                self.current_tool_name = None\n            if self.streaming_state == StreamingState.PARSING_NAME_COMPLETED:\n                self.streaming_state = StreamingState.WAITING_FOR_TOOL_KEY\n            if self.streaming_state in [\n                StreamingState.PARSING_ARGUMENTS,\n                StreamingState.PARSING_ARGUMENTS_COMPLETED,\n            ]:\n                if self.streaming_state == StreamingState.PARSING_ARGUMENTS_COMPLETED:\n                    self.streaming_state = StreamingState.WAITING_FOR_TOOL_KEY\n                current_tool_call_modified = True\n                if current_tool_call.function.arguments is None:\n                    current_tool_call.function.arguments = delta_to_be_parsed\n                else:\n                    current_tool_call.function.arguments += delta_to_be_parsed\n                if streaming_state_before_parse != StreamingState.PARSING_ARGUMENTS:\n                    # It\'s the first chunk of arg. let\'s lstrip it\n                    current_tool_call.function.arguments = (\n                        current_tool_call.function.arguments.lstrip()\n                    )\n\n        if current_tool_call_modified:\n            if self.current_tool_mistral_id is not None:\n                current_tool_call.id = self.current_tool_mistral_id\n                self.current_tool_mistral_id = None\n            self._track_streamed_args_pre_v11(current_tool_call)\n            delta_tool_calls.append(current_tool_call)\n\n        if content or len(delta_tool_calls) > 0:\n            delta_message = DeltaMessage()\n            if content:\n                delta_message.content = content\n            if len(delta_tool_calls) > 0:\n                delta_message.tool_calls = delta_tool_calls\n            return delta_message\n        else:\n            if self.streaming_state == StreamingState.ALL_TOOLS_COMPLETE:\n                return DeltaMessage()\n            else:\n                return None\n\n    def _track_streamed_args_pre_v11(self, tool_call: DeltaToolCall) -> None:\n        r"""Accumulate `tool_call` arguments into the streaming state."""\n        if tool_call.function is not None and tool_call.function.arguments is not None:\n            self.streamed_args_for_tool[self.current_tool_id] += (\n                tool_call.function.arguments\n            )\n            self.prev_tool_call_arr[self.current_tool_id]["arguments"] = (\n                self.streamed_args_for_tool[self.current_tool_id]\n            )\n\n    def _split_delta(\n        self,\n        delta_text: str,\n        stop_after_quotes: int = -1,\n        stop_after_opening_curly_braces: int = -1,\n        stop_after_closing_curly_braces: int = -1,\n        stop_after_closing_brackets: int = -1,\n        stop_after_colon: int = -1,\n        stop_after_comma: int = -1,\n    ) -> tuple[str, str]:\n        delta_to_be_parsed = ""\n        for i, c in enumerate(delta_text):\n            if c in [\'"\', "\'"]:\n                delta_to_be_parsed += c\n                stop_after_quotes -= 1\n                if stop_after_quotes == 0:\n                    return (delta_to_be_parsed, delta_text[i + 1 :])\n            elif c == "{":\n                delta_to_be_parsed += c\n                stop_after_opening_curly_braces -= 1\n                if stop_after_opening_curly_braces == 0:\n                    return (delta_to_be_parsed, delta_text[i + 1 :])\n            elif c == "}":\n                delta_to_be_parsed += c\n                stop_after_closing_curly_braces -= 1\n                if stop_after_closing_curly_braces == 0:\n                    return (delta_to_be_parsed, delta_text[i + 1 :])\n            elif c == "]":\n                delta_to_be_parsed += c\n                stop_after_closing_brackets -= 1\n                if stop_after_closing_brackets == 0:\n                    return (delta_to_be_parsed, delta_text[i + 1 :])\n            elif c == ":":\n                delta_to_be_parsed += c\n                stop_after_colon -= 1\n                if stop_after_colon == 0:\n                    return (delta_to_be_parsed, delta_text[i + 1 :])\n            elif c == ",":\n                delta_to_be_parsed += c\n                stop_after_comma -= 1\n                if stop_after_comma == 0:\n                    return (delta_to_be_parsed, delta_text[i + 1 :])\n            else:\n                delta_to_be_parsed += c\n\n        return (delta_to_be_parsed, "")\n\n    def extract_reasoning(\n        self,\n        model_output: str,\n        request: ChatCompletionRequest | ResponsesRequest,\n    ) -> tuple[str | None, str | None]:\n        if self._reasoning_encoding == "none":\n            return None, model_output\n        return super().extract_reasoning(model_output, request)\n\n    def _accept_tool_name(self, name: str) -> bool:\n        # Once `[ARGS]` or the opening `{` has moved the slot past its name,\n        # that name is final, empty included. Emitting the call with ""\n        # surfaces the malformed generation instead of dropping it.\n        return self._is_valid_tool_name(name)\n\n    def _try_extract_name(self, idx: int) -> str | None:\n        # No JSON-embedded "name" key in this format; the slot name is final.\n        return self._tool_slots[idx].name\n\n    def _extract_name_and_args(self, raw_body: str) -> tuple[str, str]:\n        # Never a {"name": ..., "arguments": ...} envelope -- a literal "name"\n        # argument key must not be mistaken for the tool name.\n        return "", self._extract_args_json(raw_body, "")\n\n    def _handle_arg_chunk(\n        self,\n        event: SemanticEvent,\n        deltas: list[DeltaToolCall],\n    ) -> None:\n        """Emit the opening ``{`` as an arg delta when the name is first sent.\n\n        When the TOOL_NAME→TOOL_ARGS transition fires, ``{`` arrives as an\n        ARG_VALUE_CHUNK before ``name_sent`` is True.  The parent emits the\n        name delta but not the ``{`` arg delta.  This override re-emits the\n        current chunk so streaming clients receive a valid JSON prefix.\n        """\n        idx = event.tool_index\n        name_sent_before = (\n            0 <= idx < len(self._tool_slots) and self._tool_slots[idx].name_sent\n        )\n        super()._handle_arg_chunk(event, deltas)\n        if (\n            event.value\n            and not name_sent_before\n            and 0 <= idx < len(self._tool_slots)\n            and self._tool_slots[idx].name_sent\n        ):\n            deltas.append(\n                DeltaToolCall(\n                    index=idx,\n                    function=DeltaFunctionCall(arguments=event.value),\n                )\n            )\n\n    def _extract_args_json(self, raw_args: str, func_name: str) -> str:\n        """Return the first complete JSON value in ``raw_args``.\n\n        v11+ tool calls are emitted as ``name{args}`` with no terminator, so a\n        model may append ordinary text after the closing brace. Parse the first\n        JSON value with ``raw_decode`` and drop any trailing output, mirroring\n        the pre-v11 path (fixes gh#48975).\n        """\n        stripped = raw_args.strip()\n        if not stripped:\n            return "{}"\n        try:\n            _, end = json.JSONDecoder().raw_decode(stripped)\n        except json.JSONDecodeError:\n            return stripped\n        return stripped[:end]\n', False), 'vllm.parser.minimax_m2': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""MiniMax M2 parser for XML-style tool calls.\n\nMiniMax M2 tool call format::\n\n    <minimax:tool_call><invoke name="get_weather">\n    <parameter name="city">Seattle</parameter>\n    </invoke></minimax:tool_call>\n\nEach ``<invoke>`` block becomes one tool call. The argument body consists\nof ``<parameter name="...">...</parameter>`` tags.\n"""\n\nfrom __future__ import annotations\n\nimport functools\nimport json\n\nimport regex as re\n\nfrom vllm.parser.engine.events import EventType\nfrom vllm.parser.engine.parser_engine import ParserEngine\nfrom vllm.parser.engine.parser_engine_config import (\n    ParserEngineConfig,\n    ParserState,\n    Transition,\n)\n\nTOOL_CALL_START = "<minimax:tool_call>"\nTOOL_CALL_END = "</minimax:tool_call>"\nTHINK_START = "<think>"\nTHINK_END = "</think>"\nINVOKE_PREFIX_DQ = \'<invoke name="\'\nINVOKE_PREFIX_SQ = "<invoke name=\'"\nINVOKE_PREFIX_UNQUOTED = "<invoke name="\nINVOKE_END = "</invoke>"\nNAME_END_DQ = \'">\'\nNAME_END_SQ = "\'>"\nNAME_END_UNQUOTED = ">"\nPARAM_START = "<parameter name="\nPARAM_END = "</parameter>"\n_PARAM_RE = re.compile(\n    r"<\\s*parameter\\s+name\\s*=\\s*"\n    r"(?:\\"(?P<dq_name>[^\\"]*)\\"|\'(?P<sq_name>[^\']*)\'|(?P<bare_name>[^>\\s]+))"\n    r"\\s*>"\n    r"(?P<value>.*?)"\n    r"(?:<\\s*/\\s*parameter\\s*>|(?=<\\s*parameter\\s+name\\s*=))",\n    re.DOTALL,\n)\n_PARTIAL_PARAM_RE = re.compile(\n    r"<\\s*parameter\\s+name\\s*=\\s*"\n    r"(?:\\"(?P<dq_name>[^\\"]*)\\"|\'(?P<sq_name>[^\']*)\'|(?P<bare_name>[^>\\s]+))"\n    r"\\s*>"\n    r"(?P<value>.*)$",\n    re.DOTALL,\n)\n\n\ndef _minimax_m2_arg_converter(raw_args: str, partial: bool) -> str:\n    params: dict[str, object] = {}\n\n    for match in _PARAM_RE.finditer(raw_args):\n        name = (\n            match.group("dq_name")\n            or match.group("sq_name")\n            or match.group("bare_name")\n            or ""\n        ).strip()\n        if not name:\n            continue\n        # Keep the value verbatim (like the glm47 converter): it is inline\n        # between `>` and `</parameter>`, so surrounding whitespace is data.\n        params[name] = match.group("value")\n\n    if partial:\n        remaining = _PARAM_RE.sub("", raw_args)\n        match = _PARTIAL_PARAM_RE.search(remaining)\n        if match:\n            name = (\n                match.group("dq_name")\n                or match.group("sq_name")\n                or match.group("bare_name")\n                or ""\n            ).strip()\n            if name:\n                # Verbatim, same as the complete-match loop above.\n                params[name] = match.group("value")\n\n    return json.dumps(params, ensure_ascii=False)\n\n\n@functools.cache\ndef minimax_m2_config() -> ParserEngineConfig:\n    return ParserEngineConfig(\n        name="minimax_m2",\n        initial_state=ParserState.REASONING,\n        wait_for_reasoning=True,\n        terminals={\n            "THINK_START": THINK_START,\n            "THINK_END": THINK_END,\n            "TOOL_START": TOOL_CALL_START,\n            "PARAM_START": PARAM_START,\n            "PARAM_END": PARAM_END,\n            "TOOL_END": TOOL_CALL_END,\n            "INVOKE_PREFIX_DQ": INVOKE_PREFIX_DQ,\n            "INVOKE_PREFIX_SQ": INVOKE_PREFIX_SQ,\n            "INVOKE_PREFIX_UNQUOTED": INVOKE_PREFIX_UNQUOTED,\n            "INVOKE_END": INVOKE_END,\n            "NAME_END_DQ": NAME_END_DQ,\n            "NAME_END_SQ": NAME_END_SQ,\n            "NAME_END_UNQUOTED": NAME_END_UNQUOTED,\n        },\n        token_id_terminals={\n            "THINK_START": THINK_START,\n            "THINK_END": THINK_END,\n            "TOOL_START": TOOL_CALL_START,\n            "TOOL_END": TOOL_CALL_END,\n        },\n        transitions={\n            (ParserState.REASONING, "THINK_START"): Transition(\n                ParserState.REASONING,\n                (),\n            ),\n            (ParserState.REASONING, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (EventType.REASONING_END,),\n            ),\n            (ParserState.CONTENT, "THINK_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            (ParserState.REASONING, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (EventType.REASONING_END,),\n            ),\n            (ParserState.CONTENT, "TOOL_START"): Transition(\n                ParserState.TOOL_PREAMBLE,\n                (),\n            ),\n            (ParserState.TOOL_ARGS, "PARAM_START"): Transition(\n                ParserState.TOOL_ARGS,\n                (EventType.ARG_VALUE_CHUNK,),\n            ),\n            (ParserState.TOOL_ARGS, "PARAM_END"): Transition(\n                ParserState.TOOL_ARGS,\n                (EventType.ARG_VALUE_CHUNK,),\n            ),\n            (ParserState.TOOL_PREAMBLE, "TOOL_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            (ParserState.TOOL_BETWEEN, "TOOL_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            (ParserState.CONTENT, "TOOL_END"): Transition(\n                ParserState.CONTENT,\n                (),\n            ),\n            (ParserState.TOOL_ARGS, "INVOKE_END"): Transition(\n                ParserState.TOOL_BETWEEN,\n                (EventType.TOOL_CALL_END,),\n            ),\n            **{\n                (state, terminal): Transition(\n                    ParserState.TOOL_NAME,\n                    (EventType.TOOL_CALL_START,),\n                )\n                for state in (\n                    ParserState.CONTENT,\n                    ParserState.TOOL_PREAMBLE,\n                    ParserState.TOOL_BETWEEN,\n                )\n                for terminal in (\n                    "INVOKE_PREFIX_DQ",\n                    "INVOKE_PREFIX_SQ",\n                    "INVOKE_PREFIX_UNQUOTED",\n                )\n            },\n            **{\n                (ParserState.TOOL_NAME, terminal): Transition(\n                    ParserState.TOOL_ARGS,\n                    (),\n                )\n                for terminal in (\n                    "NAME_END_DQ",\n                    "NAME_END_SQ",\n                    "NAME_END_UNQUOTED",\n                )\n            },\n        },\n        arg_converter=_minimax_m2_arg_converter,\n        stream_arg_deltas=True,\n        tool_args_json=False,\n        validate_tool_names=True,\n    )\n\n\nclass MinimaxM2Parser(ParserEngine):\n    """MiniMax M2 parser backed by the deoperatortive parser engine."""\n\n    def __init__(self, tokenizer, tools=None, **kwargs) -> None:\n        kwargs.setdefault("parser_engine_config", minimax_m2_config())\n        super().__init__(tokenizer, tools, **kwargs)\n        self._think_end_token_id = self.vocab.get(THINK_END)\n\n    def extract_content_ids(self, input_ids: list[int]) -> list[int]:\n        end_id = self._think_end_token_id\n        if end_id is None:\n            return []\n        for i in range(len(input_ids) - 1, -1, -1):\n            if input_ids[i] == end_id:\n                return input_ids[i + 1 :]\n        return []\n', False), 'vllm.parser.ling3': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""Ling3 parser for reasoning and tool calls.\n\nLing3 uses the same XML tool-call format as GLM-4.7 and defaults thinking on.\nIt follows the GLM-style ``<think>`` / ``</think>`` reasoning format and\ntreats ``<tool_call>`` as an implicit reasoning terminator.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import replace\nfrom typing import TYPE_CHECKING\n\nfrom vllm.entrypoints.openai.chat_completion.protocol import ChatCompletionRequest\nfrom vllm.entrypoints.openai.responses.protocol import ResponsesRequest\nfrom vllm.parser.engine.adapters import make_adapters\nfrom vllm.parser.engine.parser_engine import ParserEngine\nfrom vllm.parser.glm47_moe import (\n    THINK_END,\n    THINK_START,\n    Glm47MoeParser,\n    glm47_moe_config,\n)\n\nif TYPE_CHECKING:\n    from vllm.tokenizers import TokenizerLike\n    from vllm.tool_parsers.abstract_tool_parser import Tool\n\n\nclass Ling3Parser(Glm47MoeParser):\n    """Ling3 parser backed by the GLM XML parser engine."""\n\n    def __init__(\n        self,\n        tokenizer: TokenizerLike,\n        tools: list[Tool] | None = None,\n        **kwargs,\n    ) -> None:\n        chat_kwargs = kwargs.get("chat_template_kwargs", {}) or {}\n        thinking = chat_kwargs.get("thinking", None)\n        enable_thinking = chat_kwargs.get("enable_thinking", None)\n        self.thinking_enabled = (\n            True\n            if thinking is None and enable_thinking is None\n            else bool(thinking) or bool(enable_thinking)\n        )\n        parser_config = replace(\n            glm47_moe_config(thinking=self.thinking_enabled),\n            name="ling3",\n        )\n        kwargs.setdefault(\n            "parser_engine_config",\n            parser_config,\n        )\n        ParserEngine.__init__(self, tokenizer, tools, **kwargs)\n\n    @property\n    def reasoning_start_str(self) -> str:\n        return THINK_START\n\n    @property\n    def reasoning_end_str(self) -> str:\n        return THINK_END\n\n    def extract_reasoning(\n        self,\n        model_output: str,\n        request: ChatCompletionRequest | ResponsesRequest,\n    ) -> tuple[str | None, str | None]:\n        if not self.thinking_enabled:\n            return None, model_output\n\n        return super().extract_reasoning(model_output, request)\n\n\n(\n    Ling3ParserReasoningAdapter,\n    Ling3ParserToolAdapter,\n) = make_adapters(Ling3Parser)\n', False), 'vllm.parser.inkling': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""Inkling parser: typed content blocks parsed by a single state machine.\n\nInkling output format (every marker is a dedicated special token)::\n\n    <|message_model|><|content_thinking|>...reasoning...<|end_message|>\n    <|message_model|><|content_text|>...visible text...<|end_message|>\n    <|message_model|><|content_invoke_tool_json|>\n        {"name":"get_weather","args":{"city":"SF"}}<|end_message|>\n\nBlocks are self-describing and may repeat in any order; sampling may\nalso end a block with the standalone ``<|content_model_end_sampling|>``\ntoken. The tool-call payload is a single JSON object whose ``name`` is\nextracted by the engine\'s name-from-args path and whose ``args`` object\nis carved out of the wrapper by :func:`_inkling_arg_converter`.\n\nNote the terminal *labels*: ``THINK_START``/``THINK_END`` are what the\nengine keys its reasoning plumbing on (``is_reasoning_end``,\n``count_reasoning_tokens``, initial-state seeding), so ``<|end_message|>``\nis labelled ``THINK_END`` here even though it ends every block kind —\nthe transition table, not the label, carries the semantics.\n"""\n\nfrom __future__ import annotations\n\nimport functools\nimport json\nfrom collections.abc import Sequence\nfrom typing import TYPE_CHECKING\n\nfrom vllm.entrypoints.generate.base.protocol import ExtractedToolCallInformation\nfrom vllm.parser.engine.events import EventType\nfrom vllm.parser.engine.parser_engine import ParserEngine\nfrom vllm.parser.engine.parser_engine_config import (\n    ParserEngineConfig,\n    ParserState,\n    Transition,\n)\n\nif TYPE_CHECKING:\n    from vllm.tokenizers import TokenizerLike\n    from vllm.tool_parsers.abstract_tool_parser import Tool\n\nMESSAGE_MODEL = "<|message_model|>"\nCONTENT_TEXT = "<|content_text|>"\nCONTENT_THINKING = "<|content_thinking|>"\nCONTENT_INVOKE_TOOL_JSON = "<|content_invoke_tool_json|>"\nCONTENT_INVOKE_TOOL_TEXT = "<|content_invoke_tool_text|>"\nCONTENT_TOOL_ERROR = "<|content_tool_error|>"\nCONTENT_MODEL_END_SAMPLING = "<|content_model_end_sampling|>"\nEND_MESSAGE = "<|end_message|>"\n\nINKLING_SPECIAL_TOKENS = (\n    MESSAGE_MODEL,\n    CONTENT_TEXT,\n    CONTENT_THINKING,\n    CONTENT_INVOKE_TOOL_JSON,\n    CONTENT_INVOKE_TOOL_TEXT,\n    CONTENT_TOOL_ERROR,\n    CONTENT_MODEL_END_SAMPLING,\n    END_MESSAGE,\n)\n\n_WS = " \\t\\r\\n"\n\n\ndef _scan_json_value(raw: str, start: int) -> int | None:\n    """Return the end index (exclusive) of the JSON object starting at\n    ``raw[start]``, or ``None`` when the object is still unterminated."""\n    depth = 0\n    in_string = False\n    escape = False\n    for i in range(start, len(raw)):\n        ch = raw[i]\n        if escape:\n            escape = False\n            continue\n        if in_string:\n            if ch == "\\\\":\n                escape = True\n            elif ch == \'"\':\n                in_string = False\n            continue\n        if ch == \'"\':\n            in_string = True\n        elif ch == "{":\n            depth += 1\n        elif ch == "}":\n            depth -= 1\n            if depth == 0:\n                return i + 1\n    return None\n\n\ndef _args_value_span(raw: str) -> str | None:\n    """Extract the raw text span of the top-level ``"args"`` value from a\n    (possibly incomplete) ``{"name":...,"args":{...}}`` wrapper.\n\n    Returns the verbatim substring (prefix-stable across growing input,\n    which the engine\'s argument-delta diffing relies on), possibly an\n    unterminated object prefix; ``None`` when the value has not started.\n    Raises ``ValueError`` when the value is not a JSON object.\n    """\n    depth = 0\n    in_string = False\n    escape = False\n    string_start = -1\n    last_string: str | None = None\n    for i, ch in enumerate(raw):\n        if escape:\n            escape = False\n            continue\n        if in_string:\n            if ch == "\\\\":\n                escape = True\n            elif ch == \'"\':\n                in_string = False\n                if depth == 1:\n                    last_string = raw[string_start + 1 : i]\n            continue\n        if ch == \'"\':\n            in_string = True\n            string_start = i\n        elif ch == ":" and depth == 1 and last_string == "args":\n            value_start = i + 1\n            while value_start < len(raw) and raw[value_start] in _WS:\n                value_start += 1\n            if value_start >= len(raw):\n                return None\n            if raw[value_start] != "{":\n                raise ValueError("Inkling tool call args must be a JSON object")\n            value_end = _scan_json_value(raw, value_start)\n            if value_end is None:\n                return raw[value_start:]\n            return raw[value_start:value_end]\n        elif ch in "{[":\n            depth += 1\n        elif ch in "}]":\n            depth -= 1\n    return None\n\n\ndef _inkling_arg_converter(raw_args: str, partial: bool) -> str:\n    """Carve the ``args`` object out of the tool-call JSON wrapper.\n\n    Why a converter at all: the engine\'s ``tool_args_json`` machinery\n    treats the *entire* TOOL_ARGS text as the tool arguments, but Inkling\'s\n    payload is the ``{"name":...,"args":{...}}`` wrapper — without a\n    converter, ``_compute_arg_delta`` streams the wrapper verbatim into\n    the OpenAI ``arguments`` field (``converter is None -> raw delta``,\n    unconditionally; ``stream_arg_deltas=False`` does not stop it).\n\n    Why a hand-rolled scanner instead of (partial) ``json.loads`` +\n    ``json.dumps``: the engine diffs successive converter outputs and\n    requires each to extend the previous one (``startswith``); a\n    violation silently drops argument deltas. Re-serialization changes\n    whitespace and closes unterminated structures differently across\n    ticks, so the only prefix-stable output is a verbatim substring of\n    the input. The scanner is also string/escape-aware so an ``"args"``\n    literal inside the name or a string value cannot mislead it, and it\n    still recovers a partial span when EOS truncates the wrapper (where\n    ``json.loads`` would fail).\n    """\n    span = _args_value_span(raw_args)\n    if span is None:\n        # No args value yet (streaming) or none at all (treat as empty).\n        return "" if partial else "{}"\n    return span\n\n\n@functools.cache\ndef inkling_config() -> ParserEngineConfig:\n    terminals = {\n        "MSG_MODEL": MESSAGE_MODEL,\n        "TEXT_START": CONTENT_TEXT,\n        "THINK_START": CONTENT_THINKING,\n        "THINK_END": END_MESSAGE,\n        "END_SAMPLING": CONTENT_MODEL_END_SAMPLING,\n        "TOOL_START": CONTENT_INVOKE_TOOL_JSON,\n        "TOOL_TEXT": CONTENT_INVOKE_TOOL_TEXT,\n        "TOOL_ERROR": CONTENT_TOOL_ERROR,\n    }\n    transitions: dict[tuple[ParserState, str], Transition] = {\n        # ── Between blocks / inside a text block ──────────────────────\n        (ParserState.CONTENT, "MSG_MODEL"): Transition(\n            ParserState.MESSAGE_HEADER,\n            (),\n        ),\n        # Opening a block that renders as visible content proves no reasoning\n        # is still open. Confirming that here is what lets DelegatingParser\n        # hand the following blocks to the tool pass: the reasoning pass only\n        # leaves its reasoning phase on an explicit reasoning-end event, and a\n        # response with no thinking block never emits one otherwise.\n        (ParserState.CONTENT, "TEXT_START"): Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        ),\n        (ParserState.CONTENT, "THINK_START"): Transition(\n            ParserState.REASONING,\n            (EventType.REASONING_START,),\n        ),\n        # A tool block confirms the same boundary, and is the one opener that\n        # can start a turn with no visible block ahead of it.\n        (ParserState.CONTENT, "TOOL_START"): Transition(\n            ParserState.TOOL_ARGS,\n            (EventType.REASONING_END, EventType.TOOL_CALL_START),\n        ),\n        # Raw / error tool blocks render as visible text.\n        (ParserState.CONTENT, "TOOL_TEXT"): Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        ),\n        (ParserState.CONTENT, "TOOL_ERROR"): Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        ),\n        # The optional function name between the model-role and content-kind\n        # markers is metadata, not visible assistant content.\n        (ParserState.MESSAGE_HEADER, "MSG_MODEL"): Transition(\n            ParserState.MESSAGE_HEADER,\n            (),\n        ),\n        (ParserState.MESSAGE_HEADER, "TEXT_START"): Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        ),\n        (ParserState.MESSAGE_HEADER, "THINK_START"): Transition(\n            ParserState.REASONING,\n            (EventType.REASONING_START,),\n        ),\n        (ParserState.MESSAGE_HEADER, "TOOL_START"): Transition(\n            ParserState.TOOL_ARGS,\n            (EventType.REASONING_END, EventType.TOOL_CALL_START),\n        ),\n        (ParserState.MESSAGE_HEADER, "TOOL_TEXT"): Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        ),\n        (ParserState.MESSAGE_HEADER, "TOOL_ERROR"): Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        ),\n        # ── Inside a thinking block ───────────────────────────────────\n        (ParserState.REASONING, "THINK_START"): Transition(\n            ParserState.REASONING,\n            (),\n        ),\n        # Defensive: tool call opening while a thinking block is still\n        # unclosed.\n        (ParserState.REASONING, "TOOL_START"): Transition(\n            ParserState.TOOL_ARGS,\n            (EventType.REASONING_END, EventType.TOOL_CALL_START),\n        ),\n    }\n    # Block-end terminals behave identically regardless of label. A\n    # closed tool block returns to CONTENT (Inkling has no section wrapper;\n    # blocks of any kind may follow), which also keeps the block-kind\n    # and role tokens out of the engine\'s tool-terminal set so the\n    # skip_tool_parsing reasoning pass still classifies reasoning.\n    for end in ("THINK_END", "END_SAMPLING"):\n        transitions[(ParserState.CONTENT, end)] = Transition(\n            ParserState.CONTENT,\n            (),\n        )\n        transitions[(ParserState.REASONING, end)] = Transition(\n            ParserState.CONTENT,\n            (EventType.REASONING_END,),\n        )\n        transitions[(ParserState.TOOL_ARGS, end)] = Transition(\n            ParserState.CONTENT,\n            (EventType.TOOL_CALL_END,),\n        )\n        transitions[(ParserState.MESSAGE_HEADER, end)] = Transition(\n            ParserState.CONTENT,\n            (EventType.TEXT_CHUNK,),\n        )\n\n    return ParserEngineConfig(\n        name="inkling",\n        # Normal generation continues after a prompt-prefilled\n        # `<|message_model|>`. Non-streaming parsing receives only the generated\n        # suffix, so begin in the corresponding message-header state as well.\n        initial_state=ParserState.MESSAGE_HEADER,\n        wait_for_reasoning=True,\n        terminals=terminals,\n        # Inkling content-kind markers are the grammar. When the engine is\n        # used through DelegatingParser, the reasoning pass can hand the tool\n        # pass reconstructed text whose token-id slice no longer contains the\n        # content-kind marker that starts the tool block, so keep Inkling on\n        # the text grammar instead of token-id-only terminal matching.\n        token_id_terminals={},\n        transitions=transitions,\n        arg_converter=_inkling_arg_converter,\n        stream_arg_deltas=True,\n        tool_args_json=True,\n        strip_trailing_reasoning_whitespace=True,\n        drop_whitespace_only_content_before_tools=True,\n        strip_content_whitespace_with_tools=False,\n        validate_tool_names=False,\n    )\n\n\nclass InklingParser(ParserEngine):\n    CONFIG_NAME = "inkling"\n\n    def __init__(\n        self,\n        tokenizer: TokenizerLike,\n        tools: list[Tool] | None = None,\n        **kwargs,\n    ) -> None:\n        kwargs.setdefault("parser_engine_config", inkling_config())\n        super().__init__(tokenizer, tools, **kwargs)\n\n    def adjust_initial_state_from_prompt(self, prompt_token_ids: Sequence[int]) -> None:\n        """Seed the initial parsing state from the prompt tail.\n\n        Mirrors the Rust parser\'s ``initialize()``: scanning the prompt\n        backwards, the last relevant special token decides whether generation\n        continues inside a thinking block, a text block, a model message\n        header, or between blocks.\n        """\n        vocab = self.vocab\n        thinking_id = vocab.get(CONTENT_THINKING)\n        text_id = vocab.get(CONTENT_TEXT)\n        model_id = vocab.get(MESSAGE_MODEL)\n        special_ids = {vocab[text] for text in INKLING_SPECIAL_TOKENS if text in vocab}\n        for token_id in reversed(prompt_token_ids):\n            if token_id == thinking_id:\n                self._engine.reset(initial_state=ParserState.REASONING)\n                self._streaming_initialized = True\n                return\n            if token_id == text_id:\n                self._engine.reset(initial_state=ParserState.CONTENT)\n                self._streaming_initialized = True\n                return\n            if token_id == model_id:\n                self._engine.reset(initial_state=ParserState.MESSAGE_HEADER)\n                self._streaming_initialized = True\n                return\n            if token_id in special_ids:\n                break\n\n    def is_reasoning_end(self, input_ids: list[int]) -> bool:\n        vocab = self.vocab\n        thinking_id = vocab.get(CONTENT_THINKING)\n        text_id = vocab.get(CONTENT_TEXT)\n        model_id = vocab.get(MESSAGE_MODEL)\n        end_sampling_id = vocab.get(CONTENT_MODEL_END_SAMPLING)\n        for token_id in reversed(input_ids):\n            if token_id in (thinking_id, model_id):\n                return False\n            if token_id in (text_id, end_sampling_id):\n                return True\n        return False\n\n    def count_reasoning_tokens(self, token_ids: Sequence[int]) -> int:\n        vocab = self.vocab\n        thinking_id = vocab.get(CONTENT_THINKING)\n        end_ids = {\n            token_id\n            for token_id in (\n                vocab.get(END_MESSAGE),\n                vocab.get(CONTENT_MODEL_END_SAMPLING),\n            )\n            if token_id is not None\n        }\n        in_reasoning = False\n        count = 0\n        for token_id in token_ids:\n            if token_id == thinking_id:\n                in_reasoning = True\n                continue\n            if token_id in end_ids:\n                in_reasoning = False\n                continue\n            if in_reasoning:\n                count += 1\n        return count\n\n    def _single_pass_parse(\n        self,\n        text: str,\n        token_ids: Sequence[int],\n        initial_state: ParserState | None = None,\n    ) -> tuple[str | None, str | None, ExtractedToolCallInformation]:\n        reasoning, content, tool_call_info = super()._single_pass_parse(\n            text, token_ids, initial_state=initial_state\n        )\n        # The engine defers content that follows tool-call events within a\n        # single pass; Inkling allows text blocks after tool-call blocks, so\n        # flush the trailing text (matching the Rust unified parser).\n        if self._deferred_content:\n            trailing = self._deferred_content\n            self._deferred_content = ""\n            content = self._strip_content_whitespace(\n                (content or "") + trailing,\n                tool_call_info.tools_called,\n            )\n            tool_call_info = ExtractedToolCallInformation(\n                tools_called=tool_call_info.tools_called,\n                tool_calls=tool_call_info.tool_calls,\n                content=content,\n            )\n        return reasoning, content, tool_call_info\n\n    @staticmethod\n    def _extract_args_value(parsed: dict) -> str | None:\n        # Inkling wraps arguments under "args" rather than "arguments".\n        for key in ("args", "arguments", "parameters"):\n            if key in parsed:\n                val = parsed[key]\n                if isinstance(val, str):\n                    return val\n                return json.dumps(val, ensure_ascii=False)\n        return None\n', False), 'vllm.parser.deepseek_v41': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""DeepSeek V4.1 reasoning and spaced DSML tool calls."""\n\nimport functools\nfrom dataclasses import replace\n\nimport regex as re\n\nfrom vllm.parser.deepseek_v4 import (\n    DeepSeekV4Parser,\n    _dsml_arg_converter,\n    deepseek_v4_config,\n)\nfrom vllm.parser.engine.parser_engine_config import ParserEngineConfig\n\nDSML_TOOL_START = "<｜DSML｜ calls>"\nDSML_TOOL_END = "</｜DSML｜ calls>"\nDSML_INVOKE_PREFIX = \'<｜DSML｜ invoke name="\'\nDSML_INVOKE_END = "</｜DSML｜ invoke>"\nDSML_PARAM_START = "<｜DSML｜ parameter"\nDSML_PARAM_CLOSE = "</｜DSML｜ parameter>"\n\n_PARAM_RE = re.compile(\n    r\'<｜DSML｜ parameter\\s+name="([^"]+)"\\s+string="(true|false)">\'\n    r"(.*?)"\n    r"(?:</｜DSML｜ parameter>|(?=<｜DSML｜ parameter\\s+name=))",\n    re.DOTALL,\n)\n_PARTIAL_PARAM_RE = re.compile(\n    r\'<｜DSML｜ parameter\\s+name="([^"]+)"\\s+string="(true|false)">\'\n    r"(.*)$",\n    re.DOTALL,\n)\n\n\n@functools.cache\ndef deepseek_v41_config(thinking: bool = False) -> ParserEngineConfig:\n    config = deepseek_v4_config(thinking=thinking)\n    terminal_overrides = {\n        "TOOL_START": DSML_TOOL_START,\n        "TOOL_END": DSML_TOOL_END,\n        "INVOKE_PREFIX": DSML_INVOKE_PREFIX,\n        "INVOKE_END": DSML_INVOKE_END,\n        "PARAM_START": DSML_PARAM_START,\n        "PARAM_CLOSE": DSML_PARAM_CLOSE,\n    }\n    return replace(\n        config,\n        name="deepseek_v41",\n        terminals={**config.terminals, **terminal_overrides},\n        token_id_terminals={\n            key: terminal_overrides.get(key, value)\n            for key, value in config.token_id_terminals.items()\n        },\n        arg_converter=functools.partial(\n            _dsml_arg_converter,\n            param_re=_PARAM_RE,\n            partial_param_re=_PARTIAL_PARAM_RE,\n        ),\n    )\n\n\nclass DeepSeekV41Parser(DeepSeekV4Parser):\n    parser_config = staticmethod(deepseek_v41_config)\n', False), 'vllm.parser.harmony': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n\nfrom __future__ import annotations\n\nimport json\nfrom collections.abc import Sequence\nfrom dataclasses import dataclass, replace\nfrom enum import Enum, auto\nfrom typing import TYPE_CHECKING, NamedTuple\n\nfrom openai_harmony import HarmonyError, Message, Role\nfrom xgrammar import StructuralTag\nfrom xgrammar.openai_tool_call_schema import BuiltinToolParam, FunctionToolParam\nfrom xgrammar.structural_tag import (\n    AnyTextFormat,\n    ConstStringFormat,\n    Format,\n    GrammarFormat,\n    JSONSchemaFormat,\n    OptionalFormat,\n    OrFormat,\n    RegexFormat,\n    SequenceFormat,\n    TagFormat,\n    TriggeredTagsFormat,\n)\n\nfrom vllm.entrypoints.chat_utils import make_tool_call_id\nfrom vllm.entrypoints.generate.base.protocol import (\n    DeltaFunctionCall,\n    DeltaMessage,\n    DeltaToolCall,\n    FunctionCall,\n)\nfrom vllm.entrypoints.openai.chat_completion.protocol import (\n    ChatCompletionRequest,\n)\nfrom vllm.entrypoints.openai.parser.harmony_utils import (\n    extract_function_from_recipient,\n    get_streamable_parser_for_assistant,\n    is_function_recipient,\n)\nfrom vllm.entrypoints.openai.responses.protocol import ResponsesRequest\nfrom vllm.logger import init_logger\nfrom vllm.parser.abstract_parser import DelegatingParser\nfrom vllm.reasoning.gptoss_reasoning_parser import GptOssReasoningParser\nfrom vllm.sampling_params import StructuredOutputsParams\nfrom vllm.tool_parsers.gptoss_tool_parser import GptOssToolParser\nfrom vllm.tool_parsers.structural_tag_registry import (\n    SimplifiedToolChoice,\n    get_function_parameters,\n    register_vllm_structural_tag,\n)\n\nif TYPE_CHECKING:\n    from openai_harmony import Message, StreamableParser\n\n\nlogger = init_logger(__name__)\n\n\nclass _SegmentType(Enum):\n    TOOL = auto()\n    REASONING = auto()\n    CONTENT = auto()\n    IGNORE = auto()\n\n    @staticmethod\n    def from_channel_and_recipient(\n        channel: str | None, recipient: str | None\n    ) -> _SegmentType:\n        if recipient and is_function_recipient(recipient):\n            return _SegmentType.TOOL\n        if channel == "analysis":\n            return _SegmentType.REASONING\n        if channel == "final" or (channel == "commentary" and recipient is None):\n            return _SegmentType.CONTENT\n        return _SegmentType.IGNORE\n\n\nclass Segment(NamedTuple):\n    channel: str | None\n    recipient: str | None\n    delta: str\n    completed_message: Message | None = None\n\n\n@dataclass\nclass ChunkResult:\n    segments: list[Segment]\n    reasoning_token_count: int\n\n\nclass HarmonyParser(DelegatingParser):\n    def __init__(self, tokenizer, tools=None, *args, **kwargs):\n        super().__init__(tokenizer, tools, *args, **kwargs)\n\n        if self.reasoning_parser and not isinstance(\n            self.reasoning_parser, GptOssReasoningParser\n        ):\n            raise ValueError(\n                "Harmony requires GptOssReasoningParser, "\n                f"got {self.reasoning_parser.__class__.__name__}."\n            )\n\n        if self.tool_parser and not isinstance(self.tool_parser, GptOssToolParser):\n            raise ValueError(\n                "Harmony requires GptOssToolParser, "\n                f"got {self.tool_parser.__class__.__name__}."\n            )\n\n        self._parser: StreamableParser | None = None\n        self._next_tool_call_index = 0\n        self._num_processed_messages = 0\n\n        # For error recovery\n        self._current_message_tokens: list[int] = []\n\n    @property\n    def _harmony_parser(self) -> StreamableParser:\n        """Lazily initializes the Harmony parser."""\n        if self._parser is None:\n            self._parser = get_streamable_parser_for_assistant()\n        return self._parser\n\n    def _poll_completed_message(self) -> Message | None:\n        messages = self._harmony_parser.messages\n        if len(messages) <= self._num_processed_messages:\n            return None\n        msg = messages[self._num_processed_messages]\n        msg.recipient = self._normalize_recipient(msg.recipient)\n        self._num_processed_messages += 1\n        return msg\n\n    def flush(self) -> list[Segment]:\n        segments: list[Segment] = []\n        try:\n            self._harmony_parser.process_eos()\n            msg = self._poll_completed_message()\n        except HarmonyError:\n            logger.warning(\n                "Harmony parser ended in a non-terminal state; returning the "\n                "recovered raw output."\n            )\n\n            final_channel = "final"\n            text = self.model_tokenizer.decode(self._current_message_tokens)\n            segments.append(\n                Segment(\n                    channel=final_channel,\n                    recipient=None,\n                    delta=text,\n                    completed_message=None,\n                )\n            )\n            msg = Message.from_role_and_content(Role.ASSISTANT, text).with_channel(\n                final_channel\n            )\n\n        # Reset to the initial assistant-parser state for the next turn.\n        self._parser = None\n        self._num_processed_messages = 0\n        self._current_message_tokens.clear()\n\n        if msg is None:\n            return segments\n\n        segments.append(\n            Segment(\n                channel=msg.channel,\n                recipient=msg.recipient,\n                delta="",\n                completed_message=msg,\n            )\n        )\n        return segments\n\n    def parse(\n        self,\n        model_output: str,\n        request: ChatCompletionRequest | ResponsesRequest,\n        enable_auto_tools: bool = False,\n        model_output_token_ids: Sequence[int] = (),\n    ) -> tuple[str | None, str | None, list[FunctionCall] | None]:\n        """Parse Harmony output from token IDs.\n\n        Tool calls are always extracted regardless of ``enable_auto_tools``.\n        Callers must decide whether to surface them.\n        """\n        result = self.process_chunk(model_output_token_ids)\n        flushed_segments = self.flush()\n        if flushed_segments:\n            result.segments.extend(flushed_segments)\n\n        reasoning_parts: list[str] = []\n        content_parts: list[str] = []\n        tool_calls: list[FunctionCall] = []\n\n        for segment in result.segments:\n            msg = segment.completed_message\n            if msg is None:\n                continue\n            if msg.author.role != "assistant" or not msg.content:\n                continue\n            text = msg.content[0].text\n            segment_type = _SegmentType.from_channel_and_recipient(\n                msg.channel, msg.recipient\n            )\n            match segment_type:\n                case _SegmentType.REASONING if self.reasoning_parser and text:\n                    reasoning_parts.append(text)\n                case _SegmentType.CONTENT if text:\n                    content_parts.append(text)\n                case _SegmentType.TOOL if self.tool_parser:\n                    recipient = msg.recipient\n                    content_type = msg.content_type\n                    assert recipient is not None\n                    if content_type is not None and "json" not in content_type:\n                        arguments = text\n                    else:\n                        try:\n                            arguments = json.dumps(json.loads(text))\n                        except json.JSONDecodeError:\n                            arguments = text\n                    tool_calls.append(\n                        FunctionCall(\n                            name=extract_function_from_recipient(recipient),\n                            arguments=arguments,\n                        )\n                    )\n\n        reasoning = "\\n".join(reasoning_parts) or None\n        content = "\\n".join(content_parts) or None\n        return reasoning, content, tool_calls or None\n\n    def parse_delta(\n        self,\n        delta_text: str,\n        delta_token_ids: list[int],\n        request: ChatCompletionRequest | ResponsesRequest,\n        prompt_token_ids: list[int] | None = None,\n        *,\n        finished: bool,\n    ) -> DeltaMessage | None:\n        prev_recipient = self._normalize_recipient(\n            self._harmony_parser.current_recipient\n        )\n        result = self.process_chunk(delta_token_ids)\n        if finished:\n            flushed_segments = self.flush()\n            if flushed_segments:\n                result.segments.extend(flushed_segments)\n        combined_content = ""\n        combined_reasoning = ""\n        tool_messages: list[DeltaToolCall] = []\n\n        for segment in result.segments:\n            if segment.completed_message is not None:\n                prev_recipient = None\n                continue\n\n            segment_type = _SegmentType.from_channel_and_recipient(\n                segment.channel, segment.recipient\n            )\n            match segment_type:\n                case _SegmentType.REASONING if self.reasoning_parser:\n                    combined_reasoning += segment.delta\n                case _SegmentType.CONTENT:\n                    combined_content += segment.delta\n                case _SegmentType.TOOL if self.tool_parser:\n                    assert segment.recipient is not None\n                    if prev_recipient != segment.recipient:\n                        tool_name = extract_function_from_recipient(segment.recipient)\n                        tool_messages.append(\n                            DeltaToolCall(\n                                # HarmonyParser does not use _stream_state;\n                                # "random" tool_call_id_type is always used\n                                id=make_tool_call_id(),\n                                type="function",\n                                function=DeltaFunctionCall(\n                                    name=tool_name,\n                                    arguments=segment.delta,\n                                ),\n                                index=self._next_tool_call_index,\n                            )\n                        )\n                        self._next_tool_call_index += 1\n                        prev_recipient = segment.recipient\n                    elif segment.delta:\n                        idx = self._next_tool_call_index - 1\n                        if tool_messages:\n                            tool_msg = tool_messages[-1]\n                            assert tool_msg.index == idx\n                            fn = tool_msg.function\n                            assert fn is not None and fn.arguments is not None\n                            fn.arguments += segment.delta\n                        else:\n                            tool_messages.append(\n                                DeltaToolCall(\n                                    index=idx,\n                                    function=DeltaFunctionCall(arguments=segment.delta),\n                                )\n                            )\n\n        if finished:\n            self._next_tool_call_index = 0\n\n        if not combined_content and not combined_reasoning and not tool_messages:\n            return None\n\n        delta_message = DeltaMessage()\n        if combined_content:\n            delta_message.content = combined_content\n        if combined_reasoning:\n            delta_message.reasoning = combined_reasoning\n        if tool_messages:\n            delta_message.tool_calls = tool_messages\n\n        # Suppress reasoning deltas if not requested\n        if delta_message and not request.include_reasoning:\n            delta_message.reasoning = None\n\n            # If only reasoning was in the message (no content, no tool_calls)\n            # skip emitting entirely\n            if not delta_message.content and not delta_message.tool_calls:\n                return None\n\n        return delta_message\n\n    def process_chunk(self, token_ids: Sequence[int]) -> ChunkResult:\n        if not token_ids:\n            return ChunkResult(segments=[], reasoning_token_count=0)\n\n        segments: list[Segment] = []\n        reasoning_token_count = 0\n        for token_id in token_ids:\n            self._harmony_parser.process(token_id)\n            channel = self._harmony_parser.current_channel\n            recipient = self._normalize_recipient(\n                self._harmony_parser.current_recipient\n            )\n            delta = self._harmony_parser.last_content_delta or ""\n            completed_message = self._poll_completed_message()\n\n            if completed_message is not None:\n                self._current_message_tokens.clear()\n            else:\n                self._current_message_tokens.append(token_id)\n\n            if channel == "analysis" or (\n                channel == "commentary" and recipient is not None\n            ):\n                reasoning_token_count += 1\n\n            segments.append(\n                Segment(\n                    channel=channel,\n                    recipient=recipient,\n                    delta=delta,\n                    completed_message=completed_message,\n                )\n            )\n\n            # TODO: Optionally merge and suppress empty Segments\n\n        return ChunkResult(\n            segments=segments,\n            reasoning_token_count=reasoning_token_count,\n        )\n\n    def adjust_request(\n        self, request: ChatCompletionRequest | ResponsesRequest\n    ) -> ChatCompletionRequest | ResponsesRequest:\n        request = _adjust_output_format(request)\n        return super().adjust_request(request)\n\n    @staticmethod\n    def _normalize_recipient(recipient: str | None) -> str | None:\n        """Remove constrained formats misparsed into recipients by older Harmony."""\n        if recipient is None:\n            return None\n\n        constrain_index = recipient.find("<|constrain|>")\n        if constrain_index == -1:\n            return recipient\n        return recipient[:constrain_index].rstrip() or None\n\n\n_JSON_CONSTRAINS = [" json", " <|constrain|>json"]\n# Harmomy\'s stop tokens are <|return|>, <|call|>, <|endoftext|>\n# They are represented as "" since xgrammar disallows stop tokens while\n# under constraints, leading to bad or infinite generations.\n_END_TAG = ["<|end|>", ""]\n_FINAL_BEGIN = "<|channel|>final{constrain}<|message|>"\n_TOOL_CALL_CHANNELS = [\n    "<|channel|>commentary",\n    "<|channel|>analysis",\n    "<|channel|>final",\n]\n_FUNCTION_CALL_BEGINS = [\n    " to=functions.{name}{channel}{constrain}<|message|>",\n    "{channel} to=functions.{name}{constrain}<|message|>",\n]\n_JSON_CONTENT = JSONSchemaFormat(json_schema={"type": "object"})\n_ANY_CONTENT = AnyTextFormat()\n\n\ndef _assemble_tag(\n    allow_analysis: bool, allow_commentary: bool, content: Format\n) -> StructuralTag:\n    tags = []\n    if allow_analysis:\n        analysis_tag = OptionalFormat(\n            content=SequenceFormat(\n                elements=[\n                    TagFormat(\n                        begin="<|channel|>analysis<|message|>",\n                        content=_ANY_CONTENT,\n                        end="<|end|>",\n                    ),\n                    ConstStringFormat(value="<|start|>assistant"),\n                ]\n            )\n        )\n        tags.append(analysis_tag)\n\n    if allow_commentary:\n        commentary_tag = OptionalFormat(\n            content=SequenceFormat(\n                elements=[\n                    TagFormat(\n                        begin="<|channel|>commentary<|message|>",\n                        content=_ANY_CONTENT,\n                        end="<|end|>",\n                    ),\n                    ConstStringFormat(value="<|start|>assistant"),\n                ]\n            )\n        )\n        tags.append(commentary_tag)\n\n    tags.append(content)\n\n    return StructuralTag(format=SequenceFormat(elements=tags))\n\n\n@register_vllm_structural_tag("harmony")\ndef get_harmony_structural_tag(\n    tools: list[FunctionToolParam],\n    builtin_tools: list[BuiltinToolParam],\n    tool_choice: SimplifiedToolChoice,\n    reasoning: bool,\n    token_suffix: str = "",\n) -> StructuralTag:\n    # reasoning always enabled for Harmony\n    del reasoning, token_suffix\n\n    if builtin_tools:\n        # Fallback for built-in tools\n        tags = [\n            TagFormat(\n                begin="to=",\n                content=AnyTextFormat(excludes=["<|start|>"]),\n                end=_END_TAG,\n            )\n        ]\n        tags.extend(\n            TagFormat(\n                begin=channel + " to=",\n                content=AnyTextFormat(excludes=["<|start|>", "<|channel|>"]),\n                end=_END_TAG,\n            )\n            for channel in _TOOL_CALL_CHANNELS\n        )\n    else:\n        tags = [\n            TagFormat(\n                begin=pattern.format(\n                    name=tool.function.name, channel=channel, constrain=constrain\n                ),\n                content=JSONSchemaFormat(\n                    json_schema=get_function_parameters(tool.function)\n                ),\n                end=_END_TAG,\n            )\n            for tool in tools\n            for pattern in _FUNCTION_CALL_BEGINS\n            for constrain in _JSON_CONSTRAINS\n            for channel in _TOOL_CALL_CHANNELS\n        ]\n\n    if tool_choice == "auto":\n        tags.extend(\n            TagFormat(\n                begin=_FINAL_BEGIN.format(constrain=constrain),\n                content=_ANY_CONTENT,\n                end=_END_TAG,\n            )\n            for constrain in _JSON_CONSTRAINS + [""]\n        )\n\n    return _assemble_tag(\n        allow_analysis=True, allow_commentary=True, content=OrFormat(elements=tags)\n    )\n\n\ndef _params_to_final_content(params: StructuredOutputsParams) -> Format | None:\n    """Map StructuredOutputsParams in a XGrammar Format."""\n    if params.json_object:\n        return _JSON_CONTENT\n    if params.json is not None:\n        schema = params.json\n        if isinstance(schema, str):\n            schema = json.loads(schema)\n        return JSONSchemaFormat(json_schema=schema)\n    if params.regex is not None:\n        return RegexFormat(pattern=params.regex)\n    if params.choice is not None:\n        return OrFormat(\n            elements=[ConstStringFormat(value=choice) for choice in params.choice]\n        )\n    if params.grammar is not None:\n        return GrammarFormat(grammar=params.grammar)\n    if params.structural_tag is not None:\n        s_tag = json.loads(params.structural_tag)\n        if "structures" in s_tag:\n            # LegacyStructuralTagResponseFormat\n            return TriggeredTagsFormat(\n                triggers=s_tag["triggers"],\n                tags=[\n                    TagFormat(\n                        begin=structure["begin"],\n                        content=JSONSchemaFormat(json_schema=structure["schema"]),\n                        end=structure["end"],\n                    )\n                    for structure in s_tag["structures"]\n                ],\n            )\n        # StructuralTagResponseFormat\n        return StructuralTag.model_validate(s_tag).format\n    return None\n\n\ndef _adjust_output_format(\n    request: ChatCompletionRequest | ResponsesRequest,\n) -> ChatCompletionRequest | ResponsesRequest:\n    """Canonicalize request constraints into a reasoning-aware StructuralTag."""\n    params = request.extract_structured_outputs()\n    if params is None:\n        return request\n\n    final_content = _params_to_final_content(params)\n    if final_content is None:\n        return request\n\n    if isinstance(final_content, JSONSchemaFormat):\n        content = OrFormat(\n            elements=[\n                TagFormat(\n                    begin=_FINAL_BEGIN.format(constrain=constrain),\n                    content=final_content,\n                    end=_END_TAG,\n                )\n                for constrain in _JSON_CONSTRAINS\n            ]\n        )\n    else:\n        content = TagFormat(\n            begin=_FINAL_BEGIN.format(constrain=""), content=final_content, end=_END_TAG\n        )\n    structural_tag = _assemble_tag(\n        allow_analysis=True, allow_commentary=False, content=content\n    )\n\n    request.structured_outputs = replace(\n        params,\n        json=None,\n        regex=None,\n        choice=None,\n        grammar=None,\n        json_object=None,\n        structural_tag=json.dumps(structural_tag.model_dump()),\n    )\n    if isinstance(request, ResponsesRequest):\n        request.text = None\n    else:\n        request.response_format = None\n    return request\n', False), 'vllm.tool_parsers.gemma4_utils': ('# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n# Copyright 2025 Google Inc. HuggingFace Inc. team. All rights reserved.\n\n"""Gemma4 tool call parsing utilities for offline inference.\n\nStandalone functions that parse decoded model text to extract tool calls\nfrom Gemma4 models. These are pure-Python utilities with zero heavy\ndependencies — they work on raw decoded strings from any inference\nbackend (vLLM, HuggingFace, TGI, etc.).\n\nFor the OpenAI-compatible API server tool parser (streaming +\nnon-streaming), see ``vllm.tool_parsers.gemma4_tool_parser``.\nFor thinking/reasoning output parsing, see\n``vllm.reasoning.gemma4_utils``.\n\nUsage with vLLM offline inference::\n\n    from vllm import LLM, SamplingParams\n    from vllm.tool_parsers.gemma4_utils import (\n        parse_tool_calls,\n        has_tool_response_tag,\n    )\n\n    llm = LLM(model="google/gemma-4-it")\n    outputs = llm.generate(prompt, SamplingParams(...))\n    text = tokenizer.decode(outputs[0].outputs[0].token_ids, skip_special_tokens=False)\n\n    # Extract tool calls\n    tool_calls = parse_tool_calls(text)\n    for tc in tool_calls:\n        print(f"{tc[\'name\']}({tc[\'arguments\']})")\n\nPorted from ``transformers.models.gemma4.utils_gemma4`` so that vLLM users\ndo not need a transformers dependency for output parsing.\n"""\n\nimport regex as re\n\n_TOOL_RESPONSE_START_TAG = "<|tool_response>"\n\n\ndef _parse_tool_arguments(args_str: str) -> dict[str, str]:\n    """Parse tool call arguments from the Gemma4 compact format.\n\n    Delegates to the native ``<|"|>``-aware parser from\n    ``vllm.parser.gemma4``, which handles internal quotes, nested\n    objects, arrays, and all Gemma4 value types correctly.\n\n    Args:\n        args_str: Raw argument string from inside ``call:name{...}``.\n\n    Returns:\n        Dictionary of argument name → string value.\n    """\n    if not args_str or not args_str.strip():\n        return {}\n\n    from vllm.parser.gemma4 import _parse_gemma4_args\n\n    parsed = _parse_gemma4_args(args_str)\n    return {k: str(v) if not isinstance(v, str) else v for k, v in parsed.items()}\n\n\ndef parse_tool_calls(text: str, *, strict: bool = False) -> list[dict]:\n    """Parse tool calls from decoded Gemma4 model output.\n\n    Uses a tiered parsing strategy to handle known output variations in\n    Gemma4 models, which may emit\n    non-standard tool call formats.\n\n    Parsing tiers:\n        1. **Standard**: ``<|tool_call>call:name{args}<tool_call|>``\n           (special token IDs 48/49 in decoded text)\n        2. **Fallback** (when